function effectHTML(side,i){if(!effects)return '';const numbers=(effects.numbers||[]).filter(x=>x.side===side&&x.index===i),poison=numbers.some(x=>x.type==='damage'&&x.cause==='poison');return (poison?'<span class="poison-impact" aria-hidden="true"><b></b>'+Array.from({length:7},(_,n)=>`<i style="--bubble:${n}"></i>`).join('')+'</span>':numbers.some(x=>x.type==='damage')?'<span class="damage-impact" aria-hidden="true"><i></i><i></i><i></i><i></i></span>':'')+numbers.map((x,n)=>`<span class="floating-number ${x.type}${x.cause==='poison'?' poison-damage':''}" style="--number-index:${n}">${x.type==='shield'?icon('shield',19):''}${esc(x.text)}</span>`).join('')}
function effectClass(side,i){if(!effects)return '';const numbers=(effects.numbers||[]).filter(x=>x.side===side&&x.index===i),classes=[];if(effects.attacker?.side===side&&effects.attacker.index===i)classes.push('is-attacking');if(numbers.some(x=>x.type==='damage'))classes.push('is-hit');if(numbers.some(x=>x.type==='damage'&&x.cause==='poison'))classes.push('is-poison-hit');if(numbers.some(x=>x.type==='shield'))classes.push('is-shielded');if(numbers.some(x=>x.type==='heal'))classes.push('is-healed');return classes.join(' ')}
function tutorialBar(){let step=guideStep();if(step>=6)return '';let g=GUIDE[step];if(state.party.filter(Boolean).length<3){const solo={0:{title:'敵の予告を読もう',text:'最初は1人　攻撃・防御・回復を固有カードで組み合わせます　後で仲間が加入します',button:'カードを使ってみる'},1:{title:'攻撃カードを敵へ',text:'カードを選んで敵をタップ、または敵までドラッグして離します'},2:{title:'守り・回復も組み合わせる',text:'盾や回復カードを使いましょう　自分への効果や全体効果は戦場へのドロップでも使えます'},4:{title:'準備ができたらターンを終える',text:'敵は予告どおりに行動します　次のターンには気力と手札が補充されます'}};g=solo[step]||g}return `<section class="tutorial-bar" aria-label="操作ガイド"><div class="guide-avatar">${portrait(H(0).art)}</div><div class="guide-copy"><div class="guide-label">${H(0).name}の戦闘ガイド <span>${step+1} / 6</span></div><h2>${g.title}</h2><p>${g.text}</p></div><div class="guide-actions">${g.button?`<button class="btn primary" data-action="guide-next">${g.button}${icon('arrow',15)}</button>`:''}<button class="text-button" data-action="guide-skip">ガイドを終了</button></div></section>`}
function battle(){
 const m=E.mods(state),b=state.battle,card=b.hand[b.selected],c=card?E.cardValues(card,state):null,threat=forecast(state),playable=b.hand.some(card=>{let c=E.cardValues(card,state);return c.cost<=b.energy&&(c.components||[c]).reduce((n,p)=>n+(p.goldSpend||0),0)<=state.gold&&(c.components||[c]).reduce((n,p)=>n+(p.fuelCost||0),0)<=state.fuel&&(c.status||state.heroes[c.actor]?.hp>0)});
 return `<div class="battle-view">${tutorialBar()}<section class="battle-panel"><div class="battle-titlebar"><span class="battle-where"><b>${E.isSpecialStage(state)?'異界 ':''}第${displayedStage(state)}ステージ</b> ${E.chapterInfo(state).name} · ${state.step+1}/12地点 · ${b.type==='boss'?E.currentBoss(state).name:b.type==='elite'?(state.escalated?'強敵化':'強敵'):'戦闘'}</span><strong>${busy?'行動を解決中':`ターン ${b.turn}　あなたの行動`}</strong><button data-action="glossary" data-id="intent">攻撃予告の見方 ${icon('event',14)}</button></div><div class="battle-stage ${effects?.vfx?`cast-${effects.vfx} cast-${effects.intensity}`:''}"><div class="battle-backdrop">${scene(E.biomeIndex(state),E.isSpecialStage(state))}${ambientHTML()}</div><div class="battlefield"><div class="hero-team">${partyMembers().map((h,i)=>{if(!h.id)return '';let p=state.heroes[i],t=threat[i],targetable=['hero','dual'].includes(c?.target)&&(p.hp>0||c.revive)&&!busy;return `<button class="unit hero-unit actor${i} ${H(i).id}-motion ${!p.hp?'fallen':''} ${targetable?'targetable':''} ${effectClass('hero',i)}" data-action="hero" data-index="${i}" aria-label="${h.name} HP${p.hp}、盾${p.shield}、このまま終えるとHPが${t.loss}減る予定" ${busy?'disabled':''}><span class="hero-threat ${!busy&&t.incoming?(t.loss?'danger':'protected'):''}">${!p.hp?'戦闘不能':busy?'':t.incoming?t.loss?`HP −${t.loss} の予測`:'盾で防げる':'狙われていない'}</span><span class="unit-art">${characterArt(H(i).art)}${effectHTML('hero',i)}</span><span class="unit-label"><b>${h.name}</b><span class="shield-value">${icon('shield',14)}${p.shield}</span></span><span class="hp-bar"><i style="width:${p.hp/p.max*100}%"></i>${!busy&&t.loss&&p.hp?`<em style="width:${Math.min(p.hp,t.loss)/p.max*100}%;right:${(1-p.hp/p.max)*100}%"></em>`:''}</span><span class="unit-hp">HP ${p.hp} / ${p.max}</span><span class="hero-statuses">${p.power?'闘志'+p.power+' ':''}${p.poison?'毒'+p.poison+' ':''}${p.vulnerable?'脆弱'+p.vulnerable+' ':''}${p.regen?'再生'+p.regen:''}</span>${targetable?`<span class="target-tag">${targetPreview(card,i)}${icon('check',14)}</span>`:''}</button>`}).join('')}</div><span class="battle-divider" aria-hidden="true">／</span><div class="enemy-team">${b.enemies.map((e,i)=>{let targetable=!!c&&(!c.target||c.target==='dual')&&!busy&&e.hp>0,preview=card?damagePreview(state,card,e):null;return `<button class="unit enemy-unit ${e.fleeing?'treasure-enemy ':''}${['moth','bellbat','jelly','voidmoth','mirrorangel','eclipseorb'].includes(e.kind)?'floating-enemy':'grounded-enemy'} ${e.boss?'boss-unit':''} ${!e.hp?'fallen':''} ${bossDeathClass(i)} ${targetable?'targetable':''} ${effectClass('enemy',i)}" data-action="enemy" data-index="${i}" aria-label="${esc(e.name)} HP${e.hp} ${esc(intentText(e,state))}" ${!e.hp||busy?'disabled':''}><span class="intent ${['guard','guardAlly','mend','healAll'].includes(e.intent.kind)?'defensive':''}"><span class="intent-type">${e.fleeing?'逃走':INTENT_NAMES[e.intent.kind]}</span><em title="${esc(intentText(e,state))}">${esc(intentText(e,state,true))}</em></span><span class="unit-art">${enemyArt(e.kind)}${effectHTML('enemy',i)}${bossDeathHTML(i)}</span><span class="unit-label"><b>${esc(e.name)}</b>${e.shield?`<span class="shield-value">${icon('shield',13)}${e.shield}</span>`:''}</span><span class="hp-bar"><i style="width:${e.hp/e.max*100}%"></i></span><span class="unit-hp">HP ${e.hp} / ${e.max}</span><span class="statuses">${e.poison?`<span>毒 ${e.poison}</span>`:''}${e.weak?`<span>弱点 ${e.weak}</span>`:''}${e.stun?`<span>足止め ${e.stun}</span>`:''}${e.rage?`<span class="rage-status" title="足止め後の1ターンに攻撃ダメージ1.2倍　連続する足止めは無効。">怒り${e.stun?'（待機）':' ×1.2'}</span>`:''}${e.boss&&e.phase===2?'<span>第2形態</span>':''}${e.hp?traitChips(e):''}</span>${targetable&&preview?`<span class="target-tag enemy-target"><b>${preview.random?`${preview.minDamage}〜${preview.maxDamage}ダメージ`:preview.remaining===0?'撃破':`${preview.damage}ダメージ`}</b><small>攻撃後 HP ${preview.remaining}</small></span>`:''}</button>`}).join('')}</div></div>${diceHTML()}${phaseTransitionHTML()}${castVFX()}${effects?.banner?`<div class="battle-banner ${effects.link?'link-banner':''}"><strong>${esc(effects.banner)}</strong>${effects.subtitle?`<span>${esc(effects.subtitle)}</span>`:''}</div>`:''}${effects?.cardName?`<div class="cast-name">${icon(effects.cardIcon,20)}${esc(effects.cardName)}</div>`:''}</div><div class="battle-command"><div class="energy"><span class="energy-value">${b.energy}</span><span><b>気力</b><small>基本4 / 毎ターン回復</small></span></div><button class="link-meter ${b.linked?'linked':''}" data-action="glossary" data-id="link"><span><b>三人の連携</b><small>${b.linked?`発動：全員に盾${6+(m.linkShield||0)}・気力+${1+(m.linkEnergy||0)}`:state.party.filter(Boolean).length<3?'仲間が3人そろうと解放':`全員が行動 → 盾${6+(m.linkShield||0)}・気力+${1+(m.linkEnergy||0)}`}</small></span><span class="link-members">${partyMembers().map((h,i)=>h.id?`<i class="${b.actors.includes(i)?'on':''}">${h.name}</i>`:'').join('')}</span></button><button class="btn primary end-turn ${!playable||guideStep()===4?'recommended':''}" data-action="end" ${busy?'disabled':''}>ターンを終える ${icon('arrow',20)}<small>敵が予告どおりに行動</small></button></div></section><section class="hand-area"><div class="hand-heading"><h2>手札 <span>${b.hand.length}枚</span></h2><span class="hand-instruction">クリック／タップ、または対象へドラッグ</span><div><button data-action="piles" data-id="draw">山札 ${b.draw.length}</button><button data-action="piles" data-id="discard">捨札 ${b.discard.length}</button><button data-action="glossary" data-id="statuses">用語 ${icon('event',13)}</button></div></div><div class="selection-tray ${c?'active':''}" role="status">${c?`<span><b>${c.name}</b><small>${c.target==='dual'?'敵と仲間を1人ずつ選択':c.target==='hero'?'緑の枠の仲間を選択／ドロップ':c.target==='all'?'発動ボタン、または戦場へドロップ':'赤い枠の敵を選択／ドロップ'}</small></span><div>${(c.target==='all'||c.target==='dual'&&Number.isInteger(b.dualEnemy)&&Number.isInteger(b.dualHero))?'<button class="btn primary" data-action="cast">発動する '+icon('check',15)+'</button>':''}<button class="text-button" data-action="selected-info">詳細</button><button class="text-button" data-action="cancel">解除 ×</button></div>`:`<span>${busy?'敵の行動を見守りましょう':playable?'カードを選んで対象をタップ ／ 対象へドラッグ':b.hand.length?'気力が足りません　ターンを終えると回復します':'手札を使い切りました　ターンを終えて補充しましょう'}</span>`}</div>${handControls()}${targetDock(card)}<div class="hand hand-${handLayout()} ${effects?.deal?'dealing':''}">${handEntries().map(({card,index},position)=>cardHTML(card,index,'card',position)).join('')}${!b.hand.length?'<div class="empty-hand">手札なし　ターンを終えると新しいカードを引きます</div>':''}</div></section><details class="combat-log"><summary>戦闘記録 <span>${esc(state.log[0]||'')}</span></summary><div>${state.log.map(l=>`<p>${esc(l)}</p>`).join('')}</div></details></div>`;
}
function ending(){let won=state.phase==='won',info=endingInfo(state);return `<section class="panel content-panel ending-screen ${won?'game-clear':'game-over'}">${won?celebrationHTML():'<div class="loss-lantern" aria-hidden="true"><i></i><b>✦</b></div>'}<div class="result-crest">${icon(won?'sun':'flame',62)}</div><div class="eyebrow">${won?info.tag:'JOURNEY ENDED'}</div><h2>${won?info.title:'この旅はここまで'}</h2><p class="intro">${won?info.text:'仲間が全員倒れ、灯は消えてしまいました<br>覚えた戦略を持ってもう一度旅立ちましょう'}</p><div class="stats"><div><strong>${displayedStage(state)}</strong>到達ステージ</div><div><strong>${state.wins}</strong>勝利した戦闘</div><div><strong>${time()}</strong>旅の時間</div></div><div class="reward-actions">${won&&state.hard&&!state.endless&&state.chapter===15?'<button class="btn" data-action="endless-continue">この隊商でエンドレスへ</button>':''}${won?'<button class="btn" data-action="story-replay" data-id="ending">結末の物語をもう一度</button>':'<button class="btn" data-action="story-replay" data-id="defeat">最後の灯を読み返す</button>'}<button class="btn primary large" data-action="${practiceReturn?'practice-exit':'to-title'}">${practiceReturn?'練習を終えて戻る':'タイトルへ戻る'}${icon('arrow',18)}</button></div></section>`}
