  let combat=state.phase==='battle'&&!state.cutscene,nextRow=state.step+1,isTitle=inTitle;
  let sceneKey=screenKey(),storyPageChange=lastRenderedScreen.startsWith('story-')&&sceneKey.startsWith('story-');if(!storyPageChange&&!suppressTransitionOnce&&!viewState&&!entrance&&lastRenderedScreen&&lastRenderedScreen!==sceneKey&&preferences.motion)beginEntrance(inTitle?genericEntrance():entranceForState()||genericEntrance());suppressTransitionOnce=false;if(entrance?.stage==='closing'){ if(syncEntranceOverlay())return;$('#app').className=lastStableClass;$('#app').innerHTML=translateHTML('<div class="transition-underlay">'+entrance.previousHTML+'</div>'+entranceHTML(),preferences.language||'ja');return }let arriving=lastRenderedScreen!==sceneKey;lastRenderedScreen=sceneKey;
  const storyIdentity=!inTitle&&state.cutscene?`${sceneKey}:${preferences.language||'ja'}:${preferences.motion}:${preferences.largeText}:${preferences.mobileLayout}:${compactLayout()?(globalThis.visualViewport?.height||window.innerHeight):'wide'}`:'';
