  syncViewport();document.documentElement?.setAttribute('data-phone-screen',compactLayout()?'on':'off');document.documentElement?.setAttribute('data-compact-battle',!inTitle&&compactLayout()&&!state.cutscene&&state.phase==='battle'?'on':'off');document.documentElement?.setAttribute('data-compact-map',!inTitle&&compactLayout()&&!state.cutscene&&state.phase==='map'?'on':'off');
  document.documentElement?.setAttribute('lang',preferences.language||'ja');document.documentElement?.setAttribute('data-motion',preferences.motion?'on':'off');document.documentElement?.setAttribute('data-text',preferences.largeText?'large':'normal');
  let body=(DEBUG_MODE?'<div class="debug-build-banner">デバッグ版 · '+(state.debugOptions?.god?'GOD MODE ON · ':'')+'セーブと実績は通常版と別です <a href="./">通常版へ</a></div>':'')+header()+`<main class="shell">${practiceReturn?'<div class="practice-toolbar"><span>練習モード · 本編のデータは保持されています</span><button class="text-button" data-action="practice-exit" '+(busy?'disabled':'')+'>本編へ戻る ×</button></div>':''}${heading()}<div class="layout ${combat?'combat-layout':''} ${isTitle?'title-layout':''} ${state.cutscene?'story-layout':''}"><div class="main-content">${inTitle?titleScreen():content()}</div>${combat?'':sidebar()}</div><footer class="footer"><span>${practiceReturn?'練習中':started?'旅の時間 '+time():'通常4ステージ／高難度16ステージ・ターン制・自動保存'}</span><nav><button data-action="deck">デッキ ${state.deck.length}枚</button><button data-action="help">遊び方</button><button data-action="menu">メニュー</button></nav></footer></main>${DEBUG_MODE?'<button class="debug-launch" data-action="debug-open">⚙ デバッグ</button>':''}`;lastStableHTML=body;lastStableClass=$('#app').className;$('#app').innerHTML=translateHTML(body+entranceHTML()+purchaseHTML(),preferences.language||'ja');
  if(modal==='図鑑'&&Number($('#modal-root .encyclopedia-view')?.dataset?.pageSize)!==encyclopediaSize()){const active=document.activeElement?.id;openEncyclopedia();if(active==='encyclopedia-search')$('#encyclopedia-search')?.focus?.({preventScroll:true})}
  if(compactLayout()){phoneScreens.mountApp($('#app'),{key:screenKey()+':'+state.chapter+':'+state.step,phase:state.phase});if(modal)phoneScreens.mountModal($('#modal-root'),lastModalPositionKey)}else if(modal)restoreWideModal()
