function openEncyclopedia(){modal='図鑑';modalBase(`<h2>旅の図鑑</h2>${encyclopediaView(progress,{...encyclopediaState,...encyclopediaOptions(),size:encyclopediaSize()})}<div class="actions"><button class="btn primary" data-action="close">タイトルへ戻る</button></div>`,true)}
function openEncyclopediaDetail(group,id){modal='図鑑の詳細';modalBase(`${encyclopediaDetail(progress,group,id,encyclopediaOptions())}<div class="actions"><button class="btn primary" data-action="encyclopedia">図鑑の一覧へ</button></div>`,true)}
function openNew(){modal='新しい旅';modalBase(`<div class="eyebrow">ONE TRAVELER, A NEW JOURNEY</div><h2>最初の旅人を選ぶ</h2><p>選んだ1人とその人の固有カード10枚で出発します<br>最初の旅人はこのラン中、交代できません<br>道中で仲間と出会い、最大3人の隊商へ　序盤には必ず加入の機会があります</p><div class="starter-grid">${starterIds().map(id=>{let h=E.COMPANIONS.find(h=>h.id===id);return `<button class="starter-choice ${starter===id?'active':''}" data-action="starter" data-id="${id}" aria-pressed="${starter===id}"><span>${characterArt(h.art)}</span><strong>${h.name}<small>${h.job}</small></strong><b>HP ${h.max}</b><p>${h.passive}</p><em>${id==='eda'?'攻防一体・血を代価に強化':id==='sena'?'弱点・連射・手札の循環':id==='nico'?'毒・調合・回復':h.job}</em></button>`}).join('')}</div><div class="modal-label">最初のレリックを選ぶ</div><div class="doctrines">${E.NORMAL_RELICS.slice(0,3).map(r=>`<button class="choice ${doctrine===r.id?'active':''}" data-action="doctrine" data-id="${r.id}" aria-pressed="${doctrine===r.id}">${icon(r.icon,24)}<strong>${r.name}</strong><small>${relicText(r)}</small></button>`).join('')}</div><label class="toggle-line"><input id="guide-mode" type="checkbox" ${guideEnabled?'checked':''}><span><b>最初の戦闘で操作ガイドを表示</b><small>攻撃・守り・ターンの進め方を確認</small></span></label><label class="toggle-line"><input id="hard-mode" type="checkbox" ${hard?'checked':''}><span>高難度「夜深き旅」<small>全16ステージ　新たな土地と強大な主が待つ</small></span></label><label class="toggle-line"><input id="endless-mode" type="checkbox" ${endless?'checked':''}><span>終わりなき旅<small>高難度16ステージを繰り返し倒れるまで進む　16ステージ踏破ごとに2倍強化</small></span></label>${started?'<p class="warning">現在の旅を上書きします　残す場合は先に手動スロットへ保存してください</p>':''}<div class="actions"><button class="btn" data-action="close">戻る</button><button class="btn primary" data-action="start">${E.COMPANIONS.find(h=>h.id===starter).name}と出発する ${icon('arrow',18)}</button></div>`,true)}
function openHelp(){modal='遊び方';modalBase(`<div class="eyebrow">HOW TO PLAY</div><h2>基本はこの3つ</h2><p>目的は<b>通常4ステージ／高難度16ステージのボスを倒すこと</b>。急ぐ必要はありません<br>戦闘中もゆっくり考えてから操作できます</p><div class="help-flow"><div><span>1</span>${icon('eye',29)}<h3>予告を見る</h3><p>敵の頭上に<br><b>「ロウに7ダメージ」</b><br>次の行動が見えます</p></div><div><span>2</span>${icon('book',29)}<h3>カードを使う</h3><p><b>カード → 対象</b>の順<br>数字の分だけ気力を消費<br>盾で攻撃を防ぐのも大切</p></div><div><span>3</span>${icon('arrow',29)}<h3>ターンを終える</h3><p>敵が予告どおりに行動<br>次は<b>気力4・手札6枚</b>。<br>残りの気力は持ち越せません</p></div></div><div class="help-combo">${icon('star',27)}<div><h3>仲間を3人そろえて → 三人の連携！</h3><p>同じターンに全員が行動すると、<b>全員に盾6・気力+1</b>。1ターン1回です</p></div></div><div class="help-links"><button class="btn" data-action="roles">仲間の役割</button><button class="btn" data-action="glossary" data-id="all">全用語と固有能力の説明</button><button class="btn" data-action="journey-help">マップとセーブ</button></div><h3 class="cb-legend-title">カードのアイコン</h3>${legendHTML()}<p class="hint">数字はレリック・闘志・敵の弱点などを反映した実際の値です　詳しい説明はカード右下の目のボタンで拡大して確認できます</p><div class="actions"><button class="btn" data-action="close">ゲームに戻る</button><button class="btn primary" data-action="practice">実際に操作して覚える ${icon('arrow',17)}</button></div><p class="hint">練習中も本編のセーブはそのまま残ります<br>PCでは数字キーかQ/Wでカードを選び、Enterでターン終了、Escで選び直し</p>`,true)}
function openGlossary(id='all'){
 modal='すべての用語';let entries=id==='all'||id==='statuses'?GLOSSARY:GLOSSARY.filter(g=>g.id===id);if(!entries.length)entries=GLOSSARY;
 modalBase(`<div class="eyebrow">CARAVAN ENCYCLOPEDIA</div><h2>旅と戦闘の用語集</h2><label class="glossary-search">${icon('eye',18)}<input id="glossary-search" type="search" placeholder="用語や説明を検索（例：闘志）" aria-label="用語を検索"></label><p class="hint">${GLOSSARY.length}項目　効果量・発動タイミング・持続時間まで確認できます</p><div id="glossary-results" class="glossary-list">${glossaryArticles(entries)}</div><div class="actions">${entries.length<GLOSSARY.length?'<button class="btn" data-action="glossary" data-id="all">すべての用語を表示</button>':''}<button class="btn primary" data-action="close">ゲームに戻る</button></div>`,true);
}
function glossaryArticles(entries){return entries.length?entries.map(g=>`<article><small>${g.category}</small><h3>${g.name}</h3><p><b>${g.short}</b></p><p>${g.text}</p></article>`).join(''):'<p>一致する用語がありません</p>'}
function quickAccess(){return `<nav class="inspection-bar" aria-label="いつでも確認"><span>旅の手帳</span><button data-action="view-map">${icon('map',16)}地図</button><button data-action="relics">${icon('star',16)}レリック ${state.relics.length}</button><button data-action="deck">${icon('book',16)}デッキ ${state.deck.length}</button><button data-action="roles">${icon('heart',16)}仲間・固有能力</button><button data-action="glossary" data-id="all">${icon('event',16)}用語集</button></nav>`}
function openRoles(){modal='仲間と固有能力';modalBase(`<div class="eyebrow">TRAVELERS & PASSIVES</div><h2>仲間と固有能力</h2><div class="role-cards">${partyMembers().map((h,i)=>h.id?`<article class="role-card actor${i}"><div>${characterArt(h.art)}</div><h3>${h.name}${h.id===state.starterId?' ★':''}<small>${h.job} · HP ${state.heroes[i].hp}/${state.heroes[i].max}</small></h3><p><b class="passive-label">固有能力（常時発動）</b>${h.passive}<br><span>専用カード：${state.deck.filter(c=>E.cardOwner(c)===h.id).length}枚</span><button class="text-button" data-action="member-cards" data-id="${h.id}">この仲間のカードを見る</button></p></article>`:'').join('')}</div>${state.departed.length?`<p class="hint">この旅で別れた仲間：${state.departed.map(id=>E.COMPANIONS.find(h=>h.id===id).name).join('、')}。このラン中は再加入しません</p>`:''}<p class="hint">固有能力が効くのは本人のカードだけ（毎ターンの効果は本人にかかります）<br>倒れた仲間のカードは使えません<br>交代するとその仲間のカードと強化はデッキから外れます</p><div class="actions"><button class="btn" data-action="glossary" data-id="all">能力の用語を調べる</button><button class="btn primary" data-action="close">戻る</button></div>`,true)}
function mapLegend(){return `<div class="map-inspection-legend" aria-label="地図アイコンの説明">${Object.keys(TYPES).map(type=>`<span>${icon(TYPES[type][0],14)}${TYPES[type][1]}</span>`).join('')}</div>`}
function openMap(){if(state.demon?.active){modal='黒氷の魔王城';modalBase(`<p>第${displayedStage(state)}ステージ</p><h2>黒氷の魔王城</h2><div class="demon-map">${scene(17)}<div>${icon('boss',80)}<strong>魔王</strong></div></div><p>この追加ステージには魔王以外の戦闘・施設・イベントはありません</p><button class="btn" data-action="close">戦闘へ戻る</button>`,true);return}const canMove=compactLayout()&&state.phase==='map'&&!busy&&!state.cutscene&&!state.travel&&!inTitle;modal='全体マップ';modalBase(`<div class="eyebrow">ROUTE JOURNAL / 第${displayedStage(state)}ステージ</div><h2>全体マップ</h2><p>駒が現在地です。${state.step<0?'この章の出発点':state.step+1+'地点目'}。${canMove?'光っているマスを押すと移動します':'現在地と道を確認できます'}</p><div class="full-map-view"><div class="map-inspection map-sheet"><div class="route-scroll">${routeSVG(canMove)}</div></div>${mapLegend()}</div><div class="actions"><button class="btn primary" data-action="close">元の画面に戻る</button></div>`,true);requestAnimationFrame(()=>{let map=$('#modal-root .route-scroll');if(map)map.scrollTop=Math.max(0,818-Math.max(0,state.step)*67-map.clientHeight*.6)})}
function openRelics(){modal='所持レリック';modalBase(`<div class="eyebrow">RELIC COLLECTION</div><h2>所持レリック · ${state.relics.length}個</h2><div class="owned-relics">${state.relics.map(id=>{let r=E.RELICS.find(r=>r.id===id);return `<article class="owned-relic ${r.tier}">${icon(r.icon,30)}<div><small>${r.tier==='special'?'異界レリック':r.tier==='boss'?'ボスレリック':'通常レリック'}</small><h3>${r.name}</h3><span class="relic-rarity rarity-${r.rarity}">${RELIC_RARITIES[r.rarity].name}</span><p>${relicText(r)}</p>${r.drawback?`<p class="drawback"><b>デメリット（代償）</b><br>${r.drawback}</p>`:''}<button class="text-button" data-action="relic" data-id="${r.id}">効果の詳細</button></div></article>`}).join('')}</div><div class="actions"><button class="btn primary" data-action="close">元の画面に戻る</button></div>`,true)}
let recruitPreviewSlot=null;
function openRecruitCards(id,slot=null){if(state.phase!=='recruit'||!state.recruits.includes(id))return;const member=E.COMPANIONS.find(h=>h.id===id),kit=E.RECRUIT_DECKS[id];if(!member||!kit)return;recruitPreviewSlot=Number.isInteger(slot)?slot:null;const counts=new Map();kit.forEach(id=>counts.set(id,(counts.get(id)||0)+1));modal='加入時のカード';modalBase(`<div class="eyebrow">COMPANION CARDS</div><h2>${esc(member.name)}の追加カード</h2><p>加入すると次のカードが合計${kit.length}枚デッキに加わります</p><div class="recruit-card-list">${[...counts].map(([id,count])=>{const c=E.CARDS[id];return `<article class="recruit-card-entry" data-card-id="${id}" data-card-count="${count}"><div class="recruit-card-art">${cardIllustration(c.icon,c.actor,c.name+id)}</div><div><h3>${esc(displayCardName(c))} <span>×${count}枚</span></h3><p><b>消費気力 ${c.cost}</b> · ${esc(c.type)}</p><ul>${cardLines({id,up:0,branches:[]}).map(line=>`<li>${esc(line)}</li>`).join('')}</ul></div></article>`}).join('')}</div><div class="actions"><button class="btn primary" data-action="recruit-cards-back" data-id="${id}">加入画面に戻る</button></div>`)}
function openRecruitSwap(id){let next=E.COMPANIONS.find(h=>h.id===id);modal='交代する仲間を選択';modalBase(`<div class="eyebrow">CHOOSE WHO LEAVES</div><h2>${next.name}と交代するのは？</h2><p>外す仲間を選んでください　離脱した仲間はこのラン中は二度と加入しません</p><div class="option-list">${partyMembers().map((h,i)=>`<button class="option" data-action="recruit-outgoing" data-id="${id}" data-index="${i}" ${h.id===state.starterId?'disabled title="最初の旅人は交代できません"':''}><span class="portrait">${portrait(h.art)}</span><span><strong>${h.name}${h.id===state.starterId?' ★ 最初の旅人（固定）':''}</strong><small>${h.passive}</small><small>専用カード${state.deck.filter(c=>E.cardOwner(c)===h.id).length}枚を除去</small></span>${icon('arrow',20)}</button>`).join('')}</div><div class="actions"><button class="btn" data-action="close">交代せずに戻る</button></div>`)}
function confirmRecruit(id,slot){if(state.party[slot]===state.starterId)return;let next=E.COMPANIONS.find(h=>h.id===id),old=H(slot),cards=state.deck.filter(c=>E.cardOwner(c)===old.id);modal='仲間の交代を確認';modalBase(`<div class="eyebrow">A FAREWELL, A NEW COMPANION</div><h2>${old.name} → ${next.name}</h2><p><b>${old.name}のカード${cards.length}枚をすべて除去</b>します　強化も失われ、このラン中は再加入できません</p><p class="hint">${cards.map(c=>E.CARDS[c.id].name+(c.up?'＋'+c.up:'')).join(' / ')}</p><p><b>${next.name}の固有カード6枚を追加</b>します<br>固有能力：${next.passive}</p><button class="btn" data-action="recruit-cards" data-id="${id}" data-index="${slot}">追加されるカードを確認</button><div class="actions"><button class="btn" data-action="recruit-member" data-id="${id}">相手を選び直す</button><button class="btn primary" data-action="recruit-confirm" data-id="${id}" data-index="${slot}">この交代を確定</button></div>`)}
function openAudio(){
 modal='音量調節';
 const labels={master:['全体音量','BGM・効果音をまとめて調節'],bgm:['BGM','探索曲と戦闘曲の音量'],sfx:['効果音','攻撃・盾・回復・連携などの音量']};
 modalBase(`<div class="eyebrow">サウンド</div><h2>音量調節</h2><section class="external-audio-setting"><button class="btn ${mixer.settings.preserveExternal?'primary':''}" data-action="audio-priority" aria-pressed="${mixer.settings.preserveExternal}">外部の音楽・動画を優先：${mixer.settings.preserveExternal?'ON':'OFF'}</button><p>${mixer.settings.preserveExternal?'外部の音楽・動画とゲーム音声を同時に再生します　端末やブラウザによっては同時再生できない場合があります':'ゲームのBGM・効果音を使用します　端末によっては外部の再生が止まる場合があります'}</p></section><p class="hint">土地ごと・ボスごとに専用曲を用意した全98曲<br>全体・BGM・効果音の音量は別々に変えられます</p><p id="audio-status" role="status">${esc(mixer.status)}</p><div class="audio-sliders">${['master','bgm','sfx'].map(channel=>`<label class="audio-slider" for="audio-${channel}"><span><strong>${labels[channel][0]}</strong><output id="volume-${channel}" for="audio-${channel}">${Math.round(mixer.settings[channel]*100)}%</output></span><input id="audio-${channel}" type="range" min="0" max="100" step="1" value="${Math.round(mixer.settings[channel]*100)}" data-audio-channel="${channel}" aria-label="${labels[channel][0]}" aria-valuetext="${Math.round(mixer.settings[channel]*100)}パーセント"><small>${labels[channel][1]}</small></label>`).join('')}</div><div class="audio-buttons"><button class="btn ${mixer.settings.muted?'primary':''}" data-action="audio-mute" aria-pressed="${mixer.settings.muted}">${mixer.settings.muted?'消音を解除':'すべて消音'}</button><button class="btn" data-action="audio-test">効果音を試聴</button><button class="btn" data-action="audio-play">BGMを再生・再開</button></div><p class="hint">音量はこのブラウザに保存します　画面を閉じると音は止まります　BGMは探索中と戦闘中で切り替わります</p><div class="actions"><button class="btn primary" data-action="close">ゲームに戻る</button></div>`);
}
function openBackup(){modal='データの引き継ぎ';modalBase(`<div class="eyebrow">DATA TRANSFER</div><h2>データの引き継ぎ</h2><p>実績・旅人の解放状況・図鑑・隠し要素の進み具合・自動保存と手動記録・設定・デバッグ版のデータをひとまとめにして別の端末やブラウザへ移せます</p><div class="settings-row"><span><b>すべて書き出す</b><small>この端末のデータをファイルに保存します</small></span><button class="btn" data-action="backup-export">書き出す</button></div><div class="settings-row"><span><b>ファイルから読み込む</b><small>書き出したファイルを選びます</small></span><button class="btn" data-action="backup-file">ファイルを選ぶ</button><input type="file" id="backup-file" accept=".json,application/json,text/plain" hidden></div><div class="settings-row backup-paste"><span><b>コピーした内容を貼り付ける</b><small>旧サイトの移行ツールでコピーした文字をそのまま貼り付けます</small><textarea id="backup-text" rows="3" placeholder='{"format":"lantern-backup", ...}' aria-label="引き継ぎデータ"></textarea></span><button class="btn" data-action="backup-paste">読み込む</button></div><p class="hint">旧サイト（chatgpt.site）のデータを移す方法は <a href="migrate.html" target="_blank" rel="noopener">移行ガイド</a> を見てください　実績と解放状況は今の記録と合わせて残ります</p><div class="actions"><button class="btn primary" data-action="close">戻る</button></div>`)}
function previewBackup(text){try{pendingBackup=parseBackup(text)}catch(error){toast(error.message);return}const sum=summarizeBackup(pendingBackup),when=pendingBackup.exportedAt?new Date(pendingBackup.exportedAt).toLocaleString('ja-JP'):'不明';modal='引き継ぐ内容の確認';modalBase(`<div class="eyebrow">CONFIRM</div><h2>この内容を引き継ぎますか？</h2><ul class="backup-summary"><li>書き出した日時：${esc(when)}</li><li>実績：${sum.achievements}個</li><li>迎えた旅人：${sum.travelers}人 ／ 通算勝利：${sum.wins}</li><li>進行中の旅：${sum.run?`第${sum.run.chapter}ステージ・${sum.run.step}地点目`:'なし'}</li><li>手動記録：${sum.manualSlots}件 ／ 設定：${sum.settings?'あり':'なし'} ／ デバッグ版：${sum.debug?'あり':'なし'}</li></ul><p>実績・解放状況・図鑑はこの端末の記録と合わせて残ります。<b>進行中の旅・手動記録・設定は引き継ぐ内容で置き換わります</b>読み込み後に自動で再読み込みします</p><div class="actions"><button class="btn" data-action="close">戻る</button><button class="btn primary" data-action="backup-apply">引き継ぐ</button></div>`)}
function exportBackup(){try{save()}catch{}const url=URL.createObjectURL(new Blob([encodeBackup(globalThis.localStorage)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`lantern-caravan-all-data-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('すべてのデータを書き出しました')}
function starterIds(){const list=availableStarters(progress);if((DEBUG_MODE||unlockedFeatures(gameStorage).includes('maou'))&&!list.includes('maou'))list.push('maou');return list}
function encyclopediaOptions(){return{allKnown:DEBUG_MODE,secrets:unlockedFeatures(gameStorage)}}
function openPassword(message='',tone=''){modal='パスワード';const labels=unlockedLabels(gameStorage);modalBase(`<div class="eyebrow">PASSWORD</div><h2>パスワードを入力</h2><p>正しいパスワードを入力すると対応する機能が解放されます</p><form class="password-form" data-password-form><input id="password-input" type="text" inputmode="text" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="40" placeholder="パスワード" aria-label="パスワード"><button type="button" class="btn primary" data-action="password-submit">決定</button></form>${message?`<p class="password-result ${tone}" role="status">${esc(message)}</p>`:''}${labels.length?`<h3>解放済み</h3><ul class="password-unlocked">${labels.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>`:''}<div class="actions"><button class="btn" data-action="close">戻る</button></div>`);setTimeout(()=>$('#password-input')?.focus(),50)}
async function submitPassword(){const input=$('#password-input');if(!input)return;const result=await redeemPassword(gameStorage,input.value);if(result.status==='empty'){openPassword('パスワードを入力してください','warn');return}if(result.status==='wrong'){sound('cancel');openPassword('パスワードが違います','warn');return}if(result.status==='already'){openPassword(`「${result.entry.label}」はすでに解放済みです`,'');return}sound('relic');openPassword(`「${result.entry.label}」が解放されました！`,'ok')}
