const cardDrag=installCardDrag({
 root:$('#app'),
 read(index){
  if(busy||entrance||state.cutscene||modal||inTitle||state.phase!=='battle')return null;
  const card=state.battle.hand[index];if(!card)return null;
  const c=E.cardValues(card,state);if(c.cost>state.battle.energy||(c.components||[c]).reduce((n,p)=>n+(p.goldSpend||0),0)>state.gold||(c.components||[c]).reduce((n,p)=>n+(p.fuelCost||0),0)>state.fuel||!c.status&&!state.heroes[c.actor]?.hp)return null;
  return {uid:card.uid,index,values:c,previous:state.battle.hand[state.battle.selected]?.uid??null,instruction:c.target==='dual'?'敵か仲間へドロップした後にもう一方を選んで発動':c.target==='hero'?'仲間まで動かして離す · 対象の外で離すとキャンセル':c.target==='all'?'戦場まで動かして離すと発動 · 手札へ戻すとキャンセル':'敵まで動かして離す · 対象の外で離すとキャンセル'};
 },
 select(index){state.battle.selected=index;delete state.battle.dualEnemy;delete state.battle.dualHero;render();sound('card')},
 restore(uid){if(state.phase!=='battle')return;const i=state.battle.hand.findIndex(c=>c.uid===uid);state.battle.selected=i<0?null:i;render()},
 target(card,hit){
  if(!hit||busy||modal||inTitle||state.phase!=='battle')return null;
  const c=card.values,unit=hit.closest('.unit')||hit.closest('.card-target-dock [data-action]'),stage=hit.closest('.battle-stage');
  if(c.target==='all')return stage?{element:stage,kind:'all',label:'ここで離すと「'+c.name+'」を発動'}:null;
  if(!unit||unit.disabled)return null;
  const i=Number(unit.dataset.index);
  if(['hero','dual'].includes(c.target)&&unit.dataset.action==='hero'&&(state.heroes[i]?.hp>0||c.revive))return {element:unit,kind:'hero',index:i,label:H(i).name+'：'+targetPreview(state.battle.hand[card.index],i)+' · 離して使う'};
  if((!c.target||c.target==='dual')&&unit.dataset.action==='enemy'&&state.battle.enemies[i]?.hp>0){const enemy=state.battle.enemies[i],p=damagePreview(state,state.battle.hand[card.index],enemy);return {element:unit,kind:'enemy',index:i,label:enemy.name+'：'+(p?p.remaining===0?'撃破できる':p.damage+'ダメージ / 残りHP '+p.remaining:'効果を付与')+' · 離して使う'}}
  return null;
 },
 cast(card,target){
  if(busy||entrance||state.cutscene||modal||state.phase!=='battle')return;
  const index=state.battle.hand.findIndex(c=>c.uid===card.uid);if(index<0)return;
  state.battle.selected=index;
  if(E.cardValues(state.battle.hand[index],state).target==='dual'){if(target.kind==='enemy')state.battle.dualEnemy=target.index;else state.battle.dualHero=target.index;render();toast('もう一方の対象を選び、発動してください');return}
  if(target.kind==='enemy')performCard(target.index,state.battle.heroTarget);
  else if(target.kind==='hero')performCard(state.battle.target,target.index);
  else performCard();
 },announce
});
