function routeSVG(interactive=true){
 const x=(row,lane)=>24+state.routeX[row][lane]*304,y=row=>818-row*67;
 let lines='',nodes='',milestones='';
 for(let row=0;row<11;row++)for(let lane=0;lane<state.route[row].length;lane++)for(let to of state.edges[row][lane]){
  let traversed=state.visited.some(v=>v[0]===state.chapter&&v[1]===row&&v[2]===lane)&&state.visited.some(v=>v[0]===state.chapter&&v[1]===row+1&&v[2]===to),upcoming=row===state.step&&lane===state.lane,mid=(x(row,lane)+x(row+1,to))/2;
  const d=`M${x(row,lane)} ${y(row)-16}C${x(row,lane)+8} ${y(row)-35} ${mid-9} ${y(row+1)+35} ${x(row+1,to)} ${y(row+1)+17}`;
  lines+=`<path d="${d}" class="map-road ${traversed?'walked':upcoming?'next-road':'unwalked'}"/>`;
 }
 if(state.step<0)for(let lane=0;lane<state.route[0].length;lane++)lines+=`<path class="map-road next-road" d="M176 895Q176 858 ${x(0,lane)} 839"/>`;
 for(let row=0;row<12;row++){
  milestones+=`<text x="10" y="${y(row)+3}" class="map-mile">${row+1}</text>`;
  for(let lane=0;lane<state.route[row].length;lane++){
   let type=state.route[row][lane],available=interactive&&E.reachable(state,row,lane),visited=state.visited.some(v=>v[0]===state.chapter&&v[1]===row&&v[2]===lane),current=row===state.step&&lane===state.lane,r=type==='boss'?28:type==='blessing'?24:type==='elite'?20:18;
   const label=type==='boss'?'未知の章の主':TYPES[type][1];
   nodes+=`<g class="map-node node-${type} ${type==='blessing'?'blessing-node':''} ${available?'available':''} ${visited?'visited-node':''} ${current?'current-node':''}" transform="translate(${x(row,lane)} ${y(row)})" ${available?'tabindex="0" role="button"':''} ${available?`data-action="node" data-row="${row}" data-lane="${lane}"`:''} aria-label="${row+1}地点目 ${label}"><title>${row+1}地点目：${label}</title><circle r="26" fill="transparent" stroke="none"/><circle class="node-seal" r="${r}" fill="${available?'#f7ebd1':visited?'#baae8b':'#e2d3ac'}" stroke="${available?'#a24a31':'#74654a'}" stroke-width="${available?3:1.3}"/>${type==='boss'?'<circle r="33" fill="none" stroke="#75452e" stroke-dasharray="2 5"/>':''}${current?'<circle r="26" fill="none" stroke="#a24a31" stroke-width="2"/>':''}<g transform="translate(-10 -10)" color="${available?'#8b3e2d':'#443e2c'}">${icon(visited&&!current?'check':TYPES[type][0],20)}</g>${available?'<circle class="node-glow" r="23" fill="none" stroke="#a25131" stroke-width="1"/>':''}</g>`;
  }
 }
 return `<svg class="route-svg" viewBox="0 0 352 930" aria-label="墨で描かれた巡礼の分岐地図"><path d="M9 17h334v895H9zM14 22h324v885H14z" class="map-inner-frame"/>${mapDecorations()}${lines}${milestones}${nodes}${mapPawn()}<g class="map-cartouche" transform="translate(176 28)"><path d="M-77-12h154l-8 23H-69Z" fill="#ddcba4" stroke="#8e7b54"/><text text-anchor="middle" y="3">第${displayedStage(state)}ステージの巡礼路</text></g><text x="176" y="132" text-anchor="middle" class="map-boss-caption">章の主の待つ門</text><text x="176" y="918" text-anchor="middle" class="map-origin">巡礼の出発点</text></svg>`;
}
function mapPoint(row,lane){return row<0?{x:176,y:900}:{x:24+state.routeX[row][lane]*304,y:818-row*67}}
function mapPawn(){let p=mapPoint(state.step,state.lane),t=state.travel,to=t?mapPoint(t.row,t.lane):p;return `<g class="map-pawn ${t?'moving':''}" transform="translate(${p.x} ${p.y-28})" aria-label="現在地の駒">${t&&preferences.motion?`<animateTransform attributeName="transform" type="translate" from="${p.x} ${p.y-28}" to="${to.x} ${to.y-28}" dur="0.9s" fill="freeze"/>`:''}<ellipse cy="13" rx="13" ry="5" fill="#463924" opacity=".35"/><path d="M-10 10-7 1-4-2v-4h8v4L7 1 10 10Z" fill="#913c28" stroke="#f7e2ae" stroke-width="2"/><circle cy="-11" r="6" fill="#bf6638" stroke="#fff1c5" stroke-width="2"/><path d="M-2 3h4M0 0v6" stroke="#f6df9f" stroke-width="1.5"/></g>`}
async function moveTo(row,lane,resume=false){
 if(busy||entrance||state.cutscene||state.phase!=='map'||!E.reachable(state,row,lane)||modal)return;
 state.travel={row,lane};busy=true;save();render();sound('footstep');announce('選んだ道へ移動しています');
 try{await wait(950);delete state.travel;if(E.enter(state,row,lane)){sound(state.phase==='battle'?(state.battle.type==='boss'?'boss':state.escalated?'ambush':'footstep'):'event')}}finally{busy=false;update();announce(state.phase==='battle'?'戦闘開始　あなたのターンです':'目的地に着きました')}
}
function map(){let next=state.step+1,choices=state.route[next].map((_,i)=>i).filter(i=>E.reachable(state,next,i)),m=E.mods(state);return `<section class="expedition-map"><div class="map-sheet chapter-paper-${state.chapter}"><div class="map-sheet-heading"><div><small class="map-kicker">THE PILGRIM’S ATLAS</small><h2>巡礼の地図</h2></div><span>${icon('boss',17)}第${displayedStage(state)}ステージ</span></div><div class="map-position"><span class="map-mini-pawn">♟</span><span>現在地：${state.step<0?'出発点':state.step+1+'地点目'}</span><button data-action="view-map">地図を広げる ${icon('eye',13)}</button></div><div class="route-scroll">${routeSVG()}</div><div class="map-legend">${Object.keys(TYPES).map(t=>`<span>${icon(TYPES[t][0],14)}${TYPES[t][1]}</span>`).join('')}</div></div><div class="route-planner"><div class="journey-illustration">${scene(E.biomeIndex(state),E.isSpecialStage(state))}<div class="travelers">${partyMembers().map(h=>h.id?`<span>${characterArt(h.art)}</span>`:'').join('')}</div></div><div class="story-strip"><span>巡礼記 / ${Math.max(1,state.step+2)}日目</span><p>${esc(E.storyBeat(state))}</p><button class="text-button" data-action="journal">これまでの旅を読む</button></div><div class="section-heading"><h2>進む道を選ぶ</h2><span>${icon('flame',15)}灯油 −${Math.max(1,2+(m.fuelCost||0))}</span></div><div class="destination-list">${choices.map((lane,i)=>{let type=state.route[next][lane],info=ROUTE_INFO[type];return `<button class="destination ${type}" data-action="node" data-row="${next}" data-lane="${lane}"><span class="destination-icon">${icon(TYPES[type][0],28)}</span><span><small>進路 ${i+1} / ${next+1}地点目</small><strong>${info.title}</strong><p>${info.desc}</p><em>${info.reward}</em>${type==='battle'&&state.chapter>0?`<small class="risk">強敵化の可能性 約${Math.round(Math.min(.4,state.chapter*.105+next*.006-.025)*100)}%</small>`:''}</span>${icon('arrow',18)}</button>`}).join('')}</div></div></section>`}
function relicChoiceScreen(offer,fromBattle=false){let owned=state.relics.length;return `<section class="panel content-panel relic-choice-screen"><div class="eyebrow">${offer.tier==='boss'?'BOSS RELIC':'RELIC CHOICE'}</div><h2>${offer.tier==='boss'?'力には代償がある':'旅のお守りを選ぶ'}</h2><p class="intro">${offer.tier==='boss'?'強力な恩恵とデメリットを持つ、ボス専用レリック':'3つの候補から1つだけ獲得できます'}</p><div class="relic-choice-grid">${offer.offeredRelics.map(id=>{let r=E.RELICS.find(r=>r.id===id);return `<button class="relic-choice ${r.tier}" data-action="relic-reward" data-id="${id}"><span class="relic-art">${icon(r.icon,42)}</span><small>${r.tier==='special'?'異界レリック':r.tier==='boss'?'ボスレリック':'通常レリック'}</small><strong>${r.name}</strong><span class="relic-rarity rarity-${r.rarity}">${RELIC_RARITIES[r.rarity].name}</span><p>${relicText(r)}</p>${r.drawback?`<div class="drawback"><b>デメリット（代償）</b><br>${r.drawback}</div>`:''}<span class="relic-select">これを受け取る ${icon('arrow',17)}</span></button>`}).join('')}</div>${!offer.offeredRelics.length?'<p class="intro">この種類のレリックはすべて所持しています</p>':''}<div class="reward-actions"><button class="btn" data-action="relic-reward" data-id="">受け取らずに進む</button></div></section>`}
function content(){
 if(state.cutscene)return storyScreen();
 if(state.phase==='demon-gate')return `<section class="panel content-panel demon-gate"><img src="assets/demon-hell.webp" alt="黒氷の魔王城"><div class="eyebrow">BEYOND THE LAST THRONE</div><h2>黒氷の門が開く</h2><p>門の向こうにいるのは魔王ただ一人　入場時に全員のHPを全回復します</p><p class="warning">毎ターン2〜4回行動　10ターン目以降は「終焉・アポカリプス」を放ちます</p><div class="actions"><button class="btn primary" data-action="demon-enter">魔王に挑む</button><button class="btn" data-action="demon-skip">元の旅路へ進む</button></div></section>`;if(state.phase==='goddess')return goddessScreen();if(state.phase==='shopupgrade')return shopUpgradeScreen();if(state.phase==='cycle')return cycleScreen();if(state.phase==='blessing')return blessingScreen();if(state.phase==='map')return map();if(state.phase==='battle')return battle();
 if(state.phase==='reward'){let r=state.reward;if(r.cardClaimed&&!r.relicClaimed)return relicChoiceScreen(r,true);return `<section class="panel content-panel victory-screen">${celebrationHTML(r.perfect)}<div class="result-crest">${icon(r.perfect?'star':'sun',54)}</div><div class="eyebrow">${r.perfect?'FIRST TURN VICTORY':'VICTORY'}</div><h2>${r.perfect?'先制殲滅！':'戦いに勝利'}</h2><p class="intro">${r.perfect?'敵が動く前に1ターンで倒し切りました<br>銀貨1.5倍・灯油+3・カード候補+1':'次の旅に備え、カードを1枚選びましょう<br>強化済みは希少　特殊カードはデッキ全体で1枚まで新しく取ると入れ替わります'}</p>${r.treasure?`<div class="treasure-banner">${icon('chest',22)}<span><b>宝抱えの灯精を討ち取った！</b><small>銀貨+${r.treasure.gold}${r.treasure.potions?` ・ 回復薬+${r.treasure.potions}`:''} ・ 通常レリック3択 ・ カード候補+1</small></span></div>`:''}<div class="reward-gold">${icon('coin',20)}銀貨 +${r.gold} 獲得済み${r.extraFuel?' / 灯油+3':''}</div>${practiceReturn?'<div class="reward-actions"><button class="btn primary large" data-action="practice-exit">練習を終えて戻る</button></div>':`<div class="reward-cards">${r.cards.map((id,i)=>`<div>${cardHTML(E.offeredCard(state,id),i,'reward')}<span class="reward-pick-label">このカードを獲得</span></div>`).join('')}</div><div class="reward-actions"><button class="btn" data-action="reward" data-id="">カードを取らずに進む</button></div>`}</section>`}
 if(state.phase==='relic')return relicChoiceScreen(state.relicOffer);
 if(state.phase==='camp'){let m=E.mods(state);return `<section class="panel content-panel camp-screen"><div class="scene-banner">${scene(E.biomeIndex(state),E.isSpecialStage(state))}</div><div class="result-crest">${icon('camp',54)}</div><h2>灯を囲む焚き火</h2><p class="intro">薪の音が夜の静けさにほどける<br>ここでは1つだけ選べます</p><div class="option-list"><button class="option" data-action="rest">${icon('heart',25)}<span><strong>休む</strong><small>${m.campHealDisabled?'レリックの代償：HPは回復しません':`生存者のHP+${18+(m.campHeal||0)}`} / 灯油+${10+(m.campFuel||0)}<br>戦闘不能者はHP18で復帰<br>現在：${campAfter()}</small></span>${icon('arrow',18)}</button><button class="option" data-action="upgrade">${icon('sword',25)}<span><strong>カードを強化</strong><small>最大3段階　確定前に強化前後と代償を比較できます</small></span>${icon('arrow',18)}</button><button class="option" data-action="fuel">${icon('flame',25)}<span><strong>灯油を精製</strong><small>灯油+${35+(m.campFuel||0)}。今回はHPが回復しません</small></span>${icon('arrow',18)}</button></div></section>`}
 if(state.phase==='event'){let ev=E.EVENTS[state.event];return `<section class="panel content-panel event-screen"><div class="result-crest">${icon('moon',54)}</div><h2>${ev.title}</h2><p class="intro">${ev.text}</p><div class="option-list">${ev.options.map((option,i)=>`<button class="option" data-action="event" data-index="${i}"><span class="option-number">${i+1}</span><span><strong>${option[0]}</strong><small>${option[1]}</small><em class="risk">${E.eventRisk(state,i)?`不運 ${Math.round(E.eventRisk(state,i)*100)}%：追加で全員のHP-${3+state.chapter*2}`:'追加の不運なし'}</em></span>${icon('arrow',18)}</button>`).join('')}</div></section>`}
 if(state.phase==='shop')return shopScreen();
 if(state.phase==='mystery')return `<section class="panel content-panel"><div class="result-crest">${icon('event',56)}</div><h2>道標のない道</h2><p class="intro">霧の向こうに何があるのか、まだ分からない<br>幸運の見込み ${Math.round(E.mysteryGoodChance(state)*100)}% / 災難 ${Math.round((1-E.mysteryGoodChance(state))*100)}%</p><div class="option-list"><button class="option" data-action="mystery-explore"><span><strong>先を確かめる</strong><small>物資・遺物・罠・伏兵など、ランダムな出来事</small></span>${icon('arrow',18)}</button><button class="option" data-action="mystery-skip" ${state.fuel<8?'disabled':''}><span><strong>遠回りで避ける</strong><small>灯油を追加で8消費して安全に進む</small></span></button></div></section>`;
 if(state.phase==='incident'){let e=state.incident,details={heal:'生存者のHP+18',supplies:'銀貨+35 / 回復薬+1 / 灯油+12',treasure:'銀貨+55 / 回復薬+1 / 灯油+12',relic:'通常レリックを3択から選ぶ',card:'3枚のカードから1枚選ぶ',goldLoss:`銀貨-${25+state.chapter*10}`,fuelLoss:`灯油-${12+state.chapter*3}`,hurt:`全員のHP-${5+state.chapter*3}`,ambush:state.chapter>1?'強敵との戦闘に入る':'通常戦闘に入る'};return `<section class="panel content-panel incident-screen"><div class="result-crest">${icon(['goldLoss','fuelLoss','hurt','ambush'].includes(e.effect)?'elite':e.effect==='treasure'?'chest':'bag',54)}</div><h2>${esc(e.title)}</h2><p class="intro">${esc(e.text)}</p><div class="incident-result">${details[e.effect]}</div><div class="reward-actions"><button class="btn primary" data-action="incident-resolve">先へ進む ${icon('arrow',18)}</button></div></section>`}
 if(state.phase==='forge')return `<section class="panel content-panel"><div class="result-crest">${icon('anvil',56)}</div><h2>古道の鍛冶場</h2><p class="intro">${state.upgradeContext?.source==='event'?'旅人の教え：今回は無料':`銀貨${E.shopPrice(state,35)}で、カードを1回強化`}<br>強化は1枚につき3回まで<br>1回ごとの変化は控えめで追加効果にも上限があります<br>候補を見てから決められます</p><div class="reward-actions"><button class="btn primary" data-action="forge-upgrade">強化するカードを選ぶ</button><button class="btn" data-action="leave">強化せず進む</button></div></section>`;
 if(state.phase==='shrine')return `<section class="panel content-panel"><div class="result-crest">${icon('sun',56)}</div><h2>巡礼の祭壇</h2><p class="intro">ここにはかつて朝を祈った人々の願いが眠る</p><div class="option-list"><button class="option" data-action="shrine" data-id="blood"><span><strong>命を捧げ、遺物を求める</strong><small>生存者のHP-10（最低1）/ 通常レリック3択</small></span></button><button class="option" data-action="shrine" data-id="purify" ${state.gold<35?'disabled':''}><span><strong>銀貨35で浄める</strong><small>全員のHP+20　戦闘不能の仲間も復帰</small></span></button><button class="option" data-action="leave"><strong>祈りだけを残して進む</strong></button></div></section>`;
 if(state.phase==='recruit')return recruitScreen();
 if(state.phase==='cardpick')return `<section class="panel content-panel"><h2>旅の技を学ぶ</h2><p class="intro">1枚だけ選んで持って帰れます<br>まれに強化済みのカードも並びます<br>特殊カードはデッキに1枚まで　新しく取ると古いほうは手放します</p><div class="reward-cards">${state.cardOffer.map((id,i)=>cardHTML(E.offeredCard(state,id),i,'event-card')).join('')}</div><div class="reward-actions"><button class="btn" data-action="event-card" data-id="">取らずに進む</button></div></section>`;
 if(state.phase==='remove')return `<section class="panel content-panel"><h2>重荷を降ろす</h2><p class="intro">1枚選んでデッキから除去できます　今回は無料</p><div class="deck-grid">${state.deck.map((c,i)=>cardHTML(c,i,'deleteCard')).join('')}</div><div class="reward-actions"><button class="btn" data-action="skip-remove">除去せずに進む</button></div></section>`;
 return ending();
}
function shopScreen(){let removeCost=E.removePrice(state);return `<section class="panel content-panel shop-screen"><div class="shop-heading"><button class="btn shop-top-return" data-action="leave">${icon('map',16)}地図へ戻る</button><span class="result-crest">${icon('shop',45)}</span><div><h2>夜道の行商人</h2><p>「どんな力にも相応の値が付くものさ。」</p></div><span class="shop-wallet">${icon('coin',19)}${state.gold} G</span></div><h3 class="shop-section-title">旅のカード</h3><p class="hint">希少な強化済みカードが並ぶこともあります　特殊カードはデッキ全体で1枚まで　購入時に以前の特殊カードは破棄されます</p><div class="shop-grid">${state.stock.map((id,i)=>`<div>${cardHTML(E.offeredCard(state,id),i,'inspectCard')}<button class="btn full" data-action="buyCard" data-index="${i}" ${state.gold<E.shopPrice(state,40)?'disabled':''}>${E.shopPrice(state,40)} Gで購入</button></div>`).join('')}</div><h3 class="shop-section-title">通常レリック / 所持で永続発動</h3><div class="shop-relic-grid">${state.shopRelics.map(stock=>{let r=E.RELICS.find(r=>r.id===stock.id);return `<article><div>${icon(r.icon,31)}<strong>${r.name}</strong></div><span class="relic-rarity rarity-${r.rarity}">${RELIC_RARITIES[r.rarity].name}</span><p>${relicText(r)}</p>${r.drawback?`<p class="drawback">代償：${r.drawback}</p>`:''}<button class="btn full" data-action="buy-relic" data-id="${r.id}" ${state.gold<stock.price?'disabled':''}>${stock.price} Gで購入</button></article>`}).join('')||'<p>この店のレリックは売り切れです</p>'}</div><div class="shop-supplies"><button class="btn" data-action="buyPotion" ${state.gold<E.shopPrice(state,25)||state.potions>=3?'disabled':''}>回復薬 ${state.potions}/3 / +1個 ${E.shopPrice(state,25)} G</button><button class="btn" data-action="buyFuel" ${state.gold<E.shopPrice(state,20)||state.fuel>=100?'disabled':''}>灯油+25 / ${E.shopPrice(state,20)} G</button><button class="btn" data-action="removeCard" ${state.gold<removeCost||state.deck.length<=6?'disabled':''}>カード除去 / ${removeCost} G</button><button class="btn" data-action="shop-upgrade" ${state.gold<E.shopForgePrice(state)||!state.deck.some(c=>c.up<3)?'disabled':''}>ランダム強化 / ${E.shopForgePrice(state)} G / 必須3択</button></div><p class="hint center">この店での除去 ${state.shopRemovals||0}回　除去するたび基本料+25 G<br>強化は段階に応じて110 / 180 / 250 G（割引前）</p><div class="reward-actions"><button class="btn primary" data-action="leave">買い物を終える ${icon('arrow',18)}</button></div></section>`}
function recruitScreen(){const vacancy=state.party.includes(null);return `<section class="panel content-panel"><div class="eyebrow">COMPANION ENCOUNTER</div><h2>焚き火にもう一つの影</h2><p class="intro">${vacancy?'空席に迎える仲間を選べます　加入を見送ることもできます':'加入する仲間を選んでから誰と交代するかを指定できます'}<br>固有カード6枚を追加　加入時HPは80%　脱退した仲間はこのラン中に戻りません</p><div class="recruit-grid">${state.recruits.map(id=>{let h=E.COMPANIONS.find(h=>h.id===id);return `<article><div>${characterArt(h.art)}</div><h3>${h.name}${h.id===state.starterId?' ★':''}<small>${h.job} · 基礎HP ${h.max}</small></h3><p><b>固有能力</b><br>${h.passive}</p><button class="btn recruit-kit" data-action="recruit-cards" data-id="${id}">追加カードを見る · ${E.RECRUIT_DECKS[id].length}枚</button><button class="btn primary full" data-action="recruit-member" data-id="${id}">${vacancy?'仲間に迎える':'迎えて交代相手を選ぶ'}</button></article>`}).join('')}</div>${!state.recruits.length?'<p>この旅で迎えられる新しい仲間はもういません</p>':''}<div class="reward-actions"><button class="btn" data-action="leave">加入を見送って進む</button></div></section>`}

function openUpgradePreview(uid){rememberDeckPosition(uid);let card=state.deck.find(c=>c.uid===uid);if(!card||card.up>=3)return;let offer=E.upgradeOffer(state,uid);if(!offer){toast('このカードは今回の条件で強化できません');return}save();let source=state.upgradeContext?.source||state.phase,cost=source==='shop'?(state.shopForge?.price??E.shopForgePrice(state)):source==='forge'?E.shopPrice(state,35):0;modal='強化前後の比較';modalBase(`<div class="eyebrow">${source==='shop'?'RANDOM OFFER':'CARD UPGRADE'} / ${card.up+1}段階目</div><h2>${offer.potency===2?'周回の二重強化：':offer.rare?'希少強化：':''}${upgradeLabel(card,offer)}への変化</h2><p>${offer.safe?'不利益を増やさずに強化します':'強化前後の効果を確認してください'}</p><div class="upgrade-comparison"><section><h3>現在 / ＋${card.up}</h3>${cardHTML(card,0,'preview-card').replace('<button','<div').replace('</button>','</div>').replace('data-action="preview-card"','')}<ul>${cardLines(card,state).map(line=>`<li>${line}</li>`).join('')}</ul><b>消費気力 ${E.cardValues(card,state).cost}</b></section><span class="upgrade-arrow">→</span><section><h3>強化後 / ＋${offer.after.up}</h3>${cardHTML(offer.after,0,'preview-card').replace('<button','<div').replace('</button>','</div>').replace('data-action="preview-card"','')}<ul>${cardLines(offer.after,state).map(line=>`<li>${line}</li>`).join('')}</ul><b>消費気力 ${E.cardValues(offer.after,state).cost}</b></section></div><p class="${offer.safe?'safe-upgrade-note':'warning'}">${offer.safe?'祝福のおかげで新しい代償は付きません（元からある代償は軽くなるか、そのまま）<br>無料で1回　確定するまで恩恵は消費されません':`消費気力・HP消費・消滅など、デメリットが増える強化もあります<br>料金 ${cost} G。${source==='shop'?'いずれか1枚の強化が必須です　比較するカードは選び直せます':'キャンセルしても費用はかかりません'}`}</p><div class="actions"><button class="btn" data-action="upgrade-back">別のカードを確認</button><button class="btn primary" data-action="apply-upgrade" data-uid="${uid}" data-id="${offer.variant}" ${state.gold<cost?'disabled':''}>${cost?cost+' Gで':''}この強化を確定</button></div>`,true)}
function openSlots(){modal='旅の記録';let slots=repository.slots();modalBase(`<div class="eyebrow">SAVE / LOAD</div><h2>旅の記録を選ぶ</h2><p>デッキ・強化3段階・レリック・仲間・戦闘中の山札まで、<br>すべて同じ状態から再開します</p><div class="save-slots">${slots.map(entry=>`<article><header><strong>${entry.slot==='auto'?'自動保存':'手動記録 '+entry.slot}</strong><span>${entry.state?new Date(entry.savedAt).toLocaleString('ja-JP'):entry.error?'読み込みエラー':'空の記録'}</span></header>${entry.state?`<div><h3>第${entry.state.chapter+1}ステージ ${E.chapterInfo(entry.state).name}</h3><p>${entry.state.step+1}/12地点 · ${entry.state.phase==='battle'?'戦闘中 / ターン'+entry.state.battle.turn:entry.state.phase==='lost'?'ゲームオーバーの記録':entry.state.phase==='won'?'踏破した旅の記録':'旅の途中'}<br>カード${entry.state.deck.length}枚 / レリック${entry.state.relics.length}個 / 銀貨${entry.state.gold}<br>${entry.state.party.map((_,i)=>E.heroInfo(entry.state,i).name).join('・')}</p></div>`:entry.error?`<p class="save-error">${esc(entry.error)}。元データは保持されています</p>`:'<p>この記録にはまだ旅がありません</p>'}<footer>${entry.state?`<button class="btn" data-action="slot-load" data-id="${entry.slot}">${entry.state.phase==='lost'?'記録を見る':'この旅を再開'}</button>`:''}${entry.slot!=='auto'&&started&&!practiceReturn?`<button class="btn" data-action="slot-save" data-id="${entry.slot}">現在の旅を記録</button>`:''}${entry.error?`<button class="btn" data-action="restore-backup" data-id="${entry.slot}">直前の記録から復元</button>`:''}</footer></article>`).join('')}</div><div class="actions"><button class="btn" data-action="export" ${!started||practiceReturn?'disabled':''}>現在の旅を書き出す</button><button class="btn" data-action="import" ${practiceReturn?'disabled':''}>ファイルを読み込む</button><button class="btn primary" data-action="close">戻る</button><input id="import-file" type="file" accept=".json,application/json" hidden></div><p class="hint">保存先はこのブラウザです　Steamクラウド同期はまだ使用しません</p>`,true)}
function confirmSlotSave(slot){let previous=repository.load(slot);if(!previous?.state){repository.save(state,slot);sound('save');openSlots();toast('手動記録'+slot+'に保存しました');return}modal='記録の上書き';modalBase(`<h2>手動記録${slot}を上書きしますか？</h2><p>保存済み：第${previous.state.chapter+1}章 / カード${previous.state.deck.length}枚 / レリック${previous.state.relics.length}個<br>今回：第${displayedStage(state)}ステージ / カード${state.deck.length}枚 / レリック${state.relics.length}個</p><div class="actions"><button class="btn" data-action="slots">戻る</button><button class="btn primary" data-action="slot-save-confirm" data-id="${slot}">この内容で上書き</button></div>`)}
function openJournal(){modal='巡礼の記録';modalBase(`<div class="eyebrow">JOURNAL</div><h2>朝へ続く足跡</h2><button class="btn" data-action="story-replay" data-id="intro">序幕を読み返す</button><div class="journal-pages">${state.journal.map((text,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><p>${esc(text)}</p></article>`).join('')}</div><div class="actions"><button class="btn primary" data-action="close">旅へ戻る</button></div>`)}
function traitChips(e){const list=enemyTraits(e),shown=list.slice(0,2);return shown.map(t=>`<span class="trait-chip trait-${t.id}" title="${esc(t.name+'：'+t.desc)}">${t.name}</span>`).join('')+(list.length>2?`<span class="trait-chip" title="${esc(list.slice(2).map(t=>t.name+'：'+t.desc).join(' / '))}">+${list.length-2}</span>`:'')}
function openEnemyInfo(index){let e=state.battle?.enemies[index];if(!e)return;modal='敵の情報';modalBase(`<div class="eyebrow">${e.boss?'CHAPTER BOSS':'ENEMY'}</div><h2>${esc(e.name)}</h2><div class="enemy-detail-art">${enemyArt(e.kind)}</div><p><b>${esc((E.ENEMIES.find(x=>x.id===e.id)||E.BOSSES.find(x=>x.id===e.id)||e).ability||'この章をさまよう敵')}</b></p>${enemyTraits(e).length?`<ul class="trait-list">${enemyTraits(e).map(t=>`<li><b>${t.name}</b>：${esc(t.desc)}</li>`).join('')}</ul>`:''}<p>HP ${e.hp} / ${e.max}、攻撃力 ${e.atk}<br>次の行動：${esc(intentText(e,state))}<br>足止め後の1ターンは怒りで攻撃ダメージ1.2倍　直前のターンも足止めされていた場合は新たな足止めは無効ですが残りターンは消えません</p><div class="actions"><button class="btn primary" data-action="close">戦闘に戻る</button></div>`)}
function openBossInfo(){if(state.phase!=='battle'||state.battle?.type!=='boss')return;let b=E.currentBoss(state);modal='章の主';modalBase(`<h2>${b.name}</h2><div class="enemy-detail-art">${enemyArt(b.id)}</div><p>${esc(b.ability)}</p><p>行動候補：${[...new Set(b.pattern)].map(k=>INTENT_NAMES[k]).join(' / ')}<br>勝利後は強力な恩恵と代償を持つボスレリックを3択から選べます</p><div class="actions"><button class="btn primary" data-action="close">地図に戻る</button></div>`)}

function phaseTransitionHTML(){return(effects?.phaseChanges||[]).map(change=>`<div class="boss-phase-transition" role="status"><div class="phase-sigil">${icon('boss',100)}</div><strong>${esc(change.name)}</strong><b>第二形態</b><div class="phase-cracks"></div></div>`).join('')}
function castVFX(){if(effects?.bossCast)return (effects.sides||['hero']).map(side=>bossCombatVFX(side==='enemy'&&effects.bossCast.mode==='strike'&&effects.numbers?.some(n=>n.side==='enemy'&&['heal','shield'].includes(n.type))?{...effects.bossCast,mode:'weave'}:effects.bossCast,side)).join('');if(!effects?.vfx)return '';let count=effects.intensity==='ultimate'?18:effects.intensity==='major'?10:5;const animations=effects.animations||(effects.sides||[effects.side==='enemy'?(effects.vfx==='heal'||effects.vfx==='ward'?'enemy':'hero'):'neutral']).map(side=>({side,vfx:effects.vfx}));return animations.map(({side,vfx})=>`<div class="cast-vfx effect-side-${side} ${vfx} ${effects.intensity} ${effects.side==='enemy'?'enemy-cast':''}" aria-hidden="true"><span class="cast-ring"></span><span class="cast-ring second"></span>${Array.from({length:count},(_,i)=>`<i style="--n:${i};--angle:${i*360/count}deg;--radius:${70+(i%4)*24}px;--delay:${(i%5)*.04}s"></i>`).join('')}<span class="cast-streak"></span>${effects.intensity==='ultimate'?'<span class="ultimate-seal">✦</span>':''}</div>`).join('')}

function ambientHTML(){return `<div class="biome-motes biome-${state.chapter}" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i style="--n:${i};left:${8+i*10}%;animation-delay:${-i*1.35}s"></i>`).join('')}</div>`}

function blessingScreen(){let damaged=state.heroes.some(h=>h.hp<h.max),canUpgrade=state.deck.some(c=>E.safeUpgradeVariants(c,state).length);return `<section class="panel content-panel blessing-screen"><div class="blessing-backdrop">${scene(E.biomeIndex(state),E.isSpecialStage(state))}</div><span class="blessing-seal">${icon('sun',58)}</span><div class="eyebrow">A LIGHT ON THE ROAD / 6地点目</div><h2>祝福の宿場</h2><p class="intro">巡礼者たちが残した灯が旅を支えてくれる<br>道の中間で受け取る、<b>6つの恩恵のうち1つ</b>。</p><div class="blessing-options"><button class="blessing-choice" data-action="blessing" data-id="copy">${icon('book',32)}<span><strong>記憶の写し</strong><em>所持カード1枚をコピー</em><small>強化や合成の効果ごと増やせる1枚（特殊カードは不可）</small></span></button><button class="blessing-choice" data-action="fusion-open">${icon('book',32)}<span><strong>灯の融合</strong><em>同じ旅人のカード2枚を1枚に</em><small>2枚の気力を合わせて効果を順に発動（強化も引き継ぎ・最大4枚分まで）</small></span></button><button class="blessing-choice" data-action="blessing" data-id="upgrade" ${!canUpgrade?'disabled':''}>${icon('sword',32)}<span><strong>清らかな鍛錬</strong><em>無料の安全強化 ×1</em><small>代償の増えない候補だけから1回強化（前後を見比べて決められます）${!canUpgrade?'現在のデッキはすべて最大強化済みです':''}</small></span></button><button class="blessing-choice" data-action="blessing" data-id="heal" ${!damaged?'disabled':''}>${icon('heart',32)}<span><strong>生命の泉</strong><em>全員のHPを最大まで回復</em><small>戦闘不能の仲間も全快で復帰　毒と脆弱を解消。${!damaged?'現在は全員が全快です':''}</small></span></button><button class="blessing-choice" data-action="blessing" data-id="gold">${icon('coin',32)}<span><strong>巡礼者の財宝</strong><em>銀貨 ＋${E.blessingGold(state)}</em><small>後のステージほど金額が増えます　ショップでの買い物・強化・除去に</small></span></button><button class="blessing-choice" data-action="blessing" data-id="fuel">${icon('flame',32)}<span><strong>灯の備蓄</strong><em>灯油100 ＋ 回復薬を3個まで補充 ＋ 銀貨80</em><small>灯油を最大まで補充　灯油が十分なときにも役立つ回復薬と路銀付き</small></span></button></div><p class="hint center">第2・4ステージ、以降は3ステージおきの中間地点に出現　異界では必ず出現<br>この地点はすべての道が合流します　恩恵を受け取るまで選び直せます</p></section>`}

function storyScreen(){
 const c=state.cutscene,frames=E.storyFrames(state),f=frames[c.index],traveler=E.COMPANIONS.find(h=>h.id===(state.starterId||state.party[0]));
 for(const frame of frames)if(frame.enTitle||frame.enText)registerTranslations([[frame.title,frame.enTitle,frame.zhTitle],[frame.text,frame.enText,frame.zhText]]);
 const art=f.image==='chapter'?scene(f.chapter??c.chapter,!!f.special):`<img src="assets/story/${f.image}.webp" alt="" class="story-illustration" draggable="false">`;
 return `<section data-presentation-key="${screenKey()}:${preferences.language||'ja'}:${preferences.motion}:${preferences.largeText}" class="story-view story-${c.kind} ${f.collapse?'loss-collapse':''}" aria-label="紙芝居の物語"><div class="story-topline"><span>${c.kind==='intro'?'序幕':c.kind==='ending'?'終幕':c.kind==='defeat'?'旅の終わり':'章の幕間'} / ${c.index+1}・${frames.length}</span><button data-action="story-skip">物語をスキップ ${icon('arrow',14)}</button></div><article class="story-page ${f.clear?'story-clear':''}" data-page="${c.kind}-${c.chapter}-${c.index}"><div class="story-art story-scene-${f.image}">${art}<div class="story-grain"></div>${f.traveler?`<div class="story-traveler">${characterArt(traveler?.art??0)}</div>`:''}${f.boss?`<div class="story-boss unknown-story-boss">${icon('boss',110)}</div>`:''}${f.company?`<div class="story-company">${partyMembers().filter(h=>h.id).map(h=>`<span>${characterArt(h.art)}</span>`).join('')}</div>`:''}${f.clear?celebrationHTML(true):''}${f.collapse?'<div class="loss-lantern" aria-hidden="true"><i></i><b>✦</b><span>灯が消えていく</span></div>':''}</div><div class="story-caption"><span>${esc(f.tag)}</span><h1>${esc(f.title)}</h1><p>${esc(f.text)}</p></div></article><div class="story-controls"><button class="btn" data-action="story-prev" ${c.index===0?'disabled':''}>前の絵へ</button><div class="story-dots">${frames.map((_,i)=>`<i class="${i===c.index?'on':''}"></i>`).join('')}</div><button class="btn primary story-next" data-action="story-next">${c.index===frames.length-1?['ending','defeat'].includes(c.kind)?'旅の記録へ':'道へ進む':'次の絵へ'} ${icon('arrow',18)}</button></div><p class="story-key-hint">自分のペースで読めます　PC：← → / Enter・Escでスキップ　途中のページも自動保存</p></section>`;
}
function entranceForState(){
 const p=state.phase;if(p==='battle'){const boss=state.battle.type==='boss',elite=state.battle.type==='elite';return{kind:boss?'boss':elite?'elite':'battle',icon:boss?'boss':elite?'elite':'sword',title:boss?E.currentBoss(state).name:elite?'強敵との遭遇':'夜の魔物が道を塞ぐ',tag:boss?'CHAPTER BOSS':elite?'DANGEROUS ENCOUNTER':'BATTLE',subtitle:E.chapterInfo(state).name}}
 const entries={goddess:['moon','湖面に女神が微笑む','選んだ恩恵を一枚のカードへ'],event:['event','物語が動き出す','道中の出来事'],mystery:['eye','霧の向こうへ','未知の道'],incident:[state.incident?.effect==='treasure'?'chest':'bag','夜道の発見','巡礼の出来事'],recruit:['heart','焚き火にもう一つの影','旅人との出会い'],shop:['shop','夜道の行商人','灯のある店'],camp:['camp','束の間の、安らぎ','野営地'],forge:['anvil','鉄と火の匂い','古道の鍛冶場'],shrine:['sun','古い祈りが残っている','巡礼の祭壇'],blessing:['sun','灯があなたを迎える','祝福の宿場']};
 if(!entries[p])return null;const [ic,title,subtitle]=entries[p];return{kind:p,icon:ic,title,subtitle,tag:p==='shop'?'TRAVELING MERCHANT':'A PAGE OF THE JOURNEY'};
}
function genericEntrance(){return{kind:'journey',icon:inTitle?'flame':state.phase==='won'?'sun':state.phase==='reward'?'star':'map',title:inTitle?'灯火のキャラバン':state.phase==='won'?'夜が明ける':state.phase==='reward'?'灯を次の旅路へ':state.cutscene?'物語の続きを':'新たな道へ',subtitle:'灯はまだ燃えている',tag:'THE PILGRIMAGE CONTINUES'}}
// Keep the mounted page while the curtain changes; rebuilding it restarts CSS story animations.
function syncEntranceOverlay(){
 const root=$('#app');if(typeof root.insertAdjacentHTML!=='function')return false;
 root.querySelector('.scene-entrance')?.remove();
 if(entrance)root.insertAdjacentHTML('beforeend',translateHTML(entranceHTML(),preferences.language||'ja'));
 else root.classList.remove('screen-arrival');
 return true;
}
function beginEntrance(entry){if(!preferences.motion||!lastStableHTML)return;clearTimeout(entranceTimer);const id=++presentationId;entrance={...entry,id,stage:'closing',previousHTML:lastStableHTML};entranceTimer=setTimeout(()=>{if(entrance?.id!==id)return;entrance.stage='opening';if(entry.kind==='boss')sound('heavy-boss');render();entranceTimer=setTimeout(()=>{if(entrance?.id===id){entrance=null;if(!syncEntranceOverlay())render();for(const resolve of entranceWaiters.splice(0))resolve()}},entry.kind==='boss'?2000:600)},420)}
function clearEntrance(){clearTimeout(entranceTimer);entrance=null;suppressTransitionOnce=true;if(!syncEntranceOverlay())render();else if(lastRenderedScreen!==screenKey())render();for(const resolve of entranceWaiters.splice(0))resolve()}
function entranceFinished(){return entrance?new Promise(resolve=>entranceWaiters.push(resolve)):Promise.resolve()}
function entranceHTML(){if(!entrance)return '';const e=entrance;return `<div class="scene-entrance entrance-${e.kind} door-${e.stage}" role="status" aria-live="polite"><div class="entrance-shutter left"></div><div class="entrance-shutter right"></div><div class="entrance-ink"></div>${e.kind==='boss'?`<div class="boss-arrival boss-arrival-${bossDefeatProfile(E.currentBoss(state)).theme} ${state.bossId==='demon_king'?'demon-arrival':''}"><div class="boss-arrival-halo"></div><div class="entrance-boss-art">${enemyArt(state.bossId)}</div><div class="boss-arrival-fractures"></div><span class="boss-arrival-label">BOSS ENCOUNTER</span></div>`:''}<div class="entrance-caption"><span>${esc(e.tag)}</span><i>${icon(e.icon,46)}</i><h2>${esc(e.title)}</h2><p>${esc(e.subtitle)}</p></div><button data-action="entrance-skip">演出をスキップ</button></div>`}
function purchaseCelebration(label,ic='bag'){const id=++presentationId;purchaseFx={id,label,icon:ic};clearTimeout(purchaseTimer);purchaseTimer=setTimeout(()=>{if(purchaseFx?.id===id){purchaseFx=null;render()}},preferences.motion?1600:250)}
function purchaseHTML(){if(!purchaseFx||state.phase!=='shop'||state.cutscene||inTitle)return '';return `<div class="purchase-celebration" role="status"><div class="purchase-rays">${Array.from({length:8},(_,i)=>`<i style="--angle:${i*45}deg"></i>`).join('')}</div><span class="purchase-seal">${icon(purchaseFx.icon,36)}</span><div><small>受け取りました</small><strong>${esc(purchaseFx.label)}</strong></div><b>${icon('check',22)}</b></div>`}
function celebrationHTML(large=false){return `<div class="clear-celebration ${large?'grand':''}" aria-hidden="true"><i class="dawn-ring"></i>${Array.from({length:large?20:12},(_,i)=>`<span style="--n:${i};--angle:${i*(large?18:30)}deg;--delay:${i%5*.09}s">✦</span>`).join('')}</div>`}

function handLayout(){if(compactLayout())return 'rail';return preferences.handLayout||((globalThis.innerWidth||1200)<=700?'rail':'grid')}
function handEntries(){return cardEntries(state.battle?.hand||[],preferences.handSort||'draw',state)}
function sortControl(key,value){return `<label class="card-sort-label">並び順 <select data-card-sort="${key}" aria-label="${key==='handSort'?'手札':'デッキ'}の並び順">${Object.entries(CARD_SORTS).filter(([id])=>key==='handSort'||id!=='draw').map(([id,label])=>`<option value="${id}" ${id===value?'selected':''}>${label}</option>`).join('')}</select></label>`}
function handControls(){return `<div class="hand-controls">${sortControl('handSort',preferences.handSort||'draw')}<div class="hand-layout-buttons" aria-label="手札の表示方法"><button data-action="hand-layout" data-id="grid" aria-pressed="${handLayout()==='grid'}">一覧表示</button><button data-action="hand-layout" data-id="rail" aria-pressed="${handLayout()==='rail'}">横並び</button></div>${handLayout()==='rail'?'<div class="hand-scroll-buttons"><button data-action="hand-scroll" data-id="left" aria-label="左の手札へ">‹</button><button data-action="hand-scroll" data-id="right" aria-label="右の手札へ">›</button><small>PC：ホイールでも移動</small></div>':'<small>すべての手札を一覧に表示 / 設定したキーでも選択</small>'}</div>`}
function changeCardView(ev){if(ev.target.dataset?.padBinding){const action=ev.target.dataset.padBinding;preferences.pad=rebind(preferences.pad,action,Number(ev.target.value));savePrefs();openControls();$('#modal-root [data-pad-binding="'+action+'"]')?.focus();return true}if(languageChange(ev))return true;const key=ev.target.dataset?.cardSort,value=ev.target.value;if(!['handSort','deckSort'].includes(key)||!CARD_SORTS[value]||key==='deckSort'&&value==='draw')return false;cardDrag.cancel();if(key==='deckSort')rememberDeckPosition();preferences[key]=value;savePrefs();if(key==='deckSort'){if(modal==='灯の融合')openFusion(fusionSelection.firstUid,fusionSelection.secondUid);else openDeck(activeDeckMode)}else render();return true}
function targetDock(card){if(!card||busy||E.cardValues(card,state).target==='all')return '';const c=E.cardValues(card,state),b=state.battle,heroes=()=>partyMembers().map((h,i)=>h.id&&(state.heroes[i].hp>0||c.revive)?`<button class="${c.target==='dual'&&b.dualHero===i?'selected-target':''}" data-action="hero" data-index="${i}">${icon('heart',14)}<b>${h.name}</b><small>${targetPreview(card,i)}</small></button>`:'').join(''),enemies=()=>b.enemies.map((e,i)=>{if(!e.hp)return '';const p=damagePreview(state,card,e);return `<button class="${c.target==='dual'&&b.dualEnemy===i?'selected-target':''}" data-action="enemy" data-index="${i}">${icon(e.boss?'boss':'sword',14)}<b>${esc(e.name)}</b><small>${p?p.random?p.minDamage+'〜'+p.maxDamage+'ダメージ':p.remaining===0?'撃破できる':p.damage+'ダメージ':'効果を付与'}</small></button>`}).join('');return `<div class="card-target-dock" aria-label="選択カードの対象"><span>${c.target==='dual'?'敵と仲間を選んで発動':'使う相手'}</span>${c.target==='dual'?'<div class="dock-heroes">'+heroes()+'</div><div class="dock-enemies">'+enemies()+'</div>':c.target==='hero'?heroes():enemies()}</div>`}

function cycleScreen(){let canUpgrade=state.deck.some(c=>E.safeUpgradeVariants(c,state,2).length);return `<section class="panel content-panel cycle-screen">${celebrationHTML(true)}<div class="result-crest">${icon('sun',64)}</div><div class="eyebrow">ANOTHER CIRCUIT / ${state.chapter+1} STAGES CLEARED</div><h2>夜はさらに深くなる</h2><p class="intro">${displayedStage(state)}ステージを踏破　次は第${state.chapter+2}ステージ、${E.chapterInfo({...state,chapter:state.chapter+1}).name}へ<br>敵の強さは引き継がれ、周回ごとにさらに増していきます</p><div class="option-list"><button class="option" data-action="cycle-choice" data-id="upgrade" ${!canUpgrade?'disabled':''}>${icon('anvil',32)}<span><strong>二重の祝福</strong><small>通常2回分の効果を強化1枠で　安全な候補から1枚を無料強化　確定前に比較できます</small></span></button><button class="option" data-action="cycle-choice" data-id="supplies">${icon('chest',32)}<span><strong>次の旅路への支度</strong><small>銀貨600と回復薬（所持3個まで）を受け取り次へ</small></span></button></div><p class="hint">どちらか1つを選択　16・32・48…ステージ踏破のたびに訪れます</p></section>`}
function openFusion(firstUid,secondUid){fusionSelection={firstUid,secondUid};if(state.phase!=='blessing')return;const first=state.deck.find(c=>c.uid===firstUid),second=state.deck.find(c=>c.uid===secondUid),result=first&&second?E.fusionPreview(state,firstUid,secondUid):null;modal='灯の融合';if(result){modalBase(`<div class="eyebrow">FUSION / CONFIRM</div><h2>二つの灯を一つに</h2><p>2枚を1枚にまとめて効果を順に発動させます<br>気力は2枚の合計でレリックのコスト補正は1枚分だけ<br>消滅するカードが混ざっていれば合成後も消滅します</p><div class="fusion-materials">${[first,second].map(c=>`<section><h3>${esc(E.cardValues(c,state).name)} · 気力${E.cardValues(c,state).cost}</h3>${cardLines(c,state).map(l=>`<p>${l}</p>`).join('')}</section>`).join('')}</div><div class="fusion-result"><h3>合成後 · 気力${E.cardValues(result,state).cost}</h3>${cardLines(result,state).map(l=>`<p>${l}</p>`).join('')}</div><p class="hint">素材の強化はそのまま残り合成後にさらに3回まで強化できます（強化は1枚目の効果にかかります）<br>祝福の宿場の恩恵を1回使います</p><div class="actions"><button class="btn" data-action="fusion-open">素材を選び直す</button><button class="btn primary" data-action="fusion-confirm" data-first="${firstUid}" data-second="${secondUid}">この合成を確定</button></div>`,true);return}const cards=first?state.deck.filter(c=>E.fusionPreview(state,firstUid,c.uid)):state.deck;modalBase(`<div class="eyebrow">FUSION / ${first?'SECOND':'FIRST'} CARD</div><h2>${first?'もう1枚の素材を選ぶ':'最初の素材を選ぶ'}</h2><p>${first?esc(E.cardValues(first,state).name)+'と同じ旅人のカードだけを表示しています':'同じ旅人のカード2枚を1枚にします　素材の強化・気力・効果を引き継ぎ、最大4枚分まで合成できます'}<br>確認して確定するまで消費はありません</p><div class="card-list-controls">${sortControl('deckSort',preferences.deckSort||'acquired')}<small>${cards.length}枚</small></div><div class="deck-grid">${cardEntries(cards,preferences.deckSort||'acquired',state).map(({card,index})=>cardHTML(card,index,first?'fusion-second':'fusion-first').replace('data-index=',`data-first="${firstUid??''}" data-index=`)).join('')}</div>${!cards.length?'<p>合成できる組み合わせがありません</p>':''}<div class="actions"><button class="btn" data-action="${first?'fusion-open':'close'}">戻る</button></div>`,true)}

function diceHTML(){const rolls=effects?.dice;if(!rolls?.length)return '';return `<div class="dice-theatre" role="status" aria-label="サイコロの結果 ${rolls.join('、')}"><span>運命の賽</span><div>${rolls.map((n,i)=>`<div class="rolling-die" style="--delay:${i*.12}s;--face:${n}"><i class="die-tumble">⚄</i><b class="die-result">${['','⚀','⚁','⚂','⚃','⚄','⚅'][n]}</b><small>${n}</small></div>`).join('')}</div><strong>出目合計 ${rolls.reduce((a,b)=>a+b,0)}</strong></div>`}

function openAchievements(){modal='巡礼の実績';modalBase(`<div class="eyebrow">ACHIEVEMENTS</div><h2>巡礼の実績 · ${Object.keys(progress.unlocked).length}/${ACHIEVEMENTS.length}</h2><p>このブラウザでの冒険の記録です　セーブ書き出しにも記録を含みます</p><div class="achievement-grid">${ACHIEVEMENTS.map(a=>`<article class="achievement ${progress.unlocked[a.id]?'unlocked':''}"><i>${icon(progress.unlocked[a.id]?'star':'shield',26)}</i><div><h3>${a.hidden&&!progress.unlocked[a.id]?'???':a.id==='secret'?'夜明けの継承者':a.name}</h3><p>${a.hidden&&!progress.unlocked[a.id]?'隠された実績':a.id==='secret'?'アウロラを解放した':a.desc}</p><small>${progress.unlocked[a.id]?new Date(progress.unlocked[a.id]).toLocaleDateString():'未達成'}</small></div></article>`).join('')}</div><div class="actions"><button class="btn primary" data-action="close">戻る</button></div>`,true)}
function shareURL(){return new URL(DEBUG_MODE?'debug/':'./',document.baseURI).href}
function openShare(){modal='共有リンク';modalBase(`<div class="eyebrow">PLAY TOGETHER</div><h2>灯火のキャラバンを共有</h2><p>このURLを友だちに送るとブラウザから遊べます　セーブと実績はプレイヤーそれぞれの端末に保存されます</p><input class="share-url" readonly value="${shareURL()}" aria-label="共有URL"><div class="actions"><button class="btn" data-action="copy-link">リンクをコピー</button><button class="btn primary" data-action="close">戻る</button></div>`)}

function languageControl(){return `<label class="language-control"><span class="sr-only">言語 / Language</span><select data-language aria-label="言語 / Language">${LANGUAGES.map(l=>`<option value="${l.id}" ${preferences.language===l.id||!preferences.language&&l.id==='ja'?'selected':''}>${l.label}</option>`).join('')}</select></label>`}
function languageChange(ev){if(!ev.target?.hasAttribute?.('data-language')&&!ev.target?.dataset?.language)return false;const language=ev.target.value;if(!LANGUAGES.some(l=>l.id===language))return false;preferences.language=language;savePrefs();const settings=modal==='設定とセーブ';if(entrance)clearEntrance();render();if(settings)openSettings();else if(modal)closeModal();return true}
registerTranslations([['無明の星骸','The Abyssal Convergence','无明星骸'],['異界レリック','Abyss relic','异界遗物'],['二重の祝福','Double blessing','双重祝福'],['実績','Achievements','成就'],['巡礼の実績','Pilgrimage achievements','巡礼成就'],['共有リンク','Share link','分享链接'],['リンクをコピー','Copy link','复制链接'],['言語 / Language','Language','语言'],['このブラウザでの冒険の記録です　セーブ書き出しにも記録を含みます','Your adventures on this browser. Progress is included in exported saves.','此浏览器上的冒险记录，也会包含在导出的存档中']]);

function bossDeathClass(index){const d=effects?.defeats?.find(d=>d.index===index);return d?`boss-dying defeat-${d.theme}`:''}
function bossDeathHTML(index){const d=effects?.defeats?.find(d=>d.index===index);return d?defeatBurst(d,icon):''}

function openControls(){modal='操作設定';modalBase(`<div class="eyebrow">CONTROLS</div><h2>操作設定</h2><div class="settings-row"><span><b>対象不要のカードを即発動</b><small>ON：全体・自身向けは押すと発動　敵や仲間を選ぶカードは押した後に対象を指定します</small></span><button class="btn ${preferences.quickCast?'primary':''}" data-action="quick-cast" aria-pressed="${!!preferences.quickCast}">${preferences.quickCast?'ON':'OFF'}</button></div><p class="hint">コントローラーは方向キーか左スティックで移動し決定で選びます<br>カードを選ぶと対象のボタンへ移り設定の数値や選択肢は左右で変えられます<br>割り当ては下で変更できます</p><h3>キーボード</h3>${pendingBinding?`<p class="binding-prompt" role="status">${ACTION_LABELS[pendingBinding]}：割り当てるキーを押してください　Escで取り消し</p>`:''}<div class="key-bindings">${Object.entries(ACTION_LABELS).map(([action,label])=>`<button class="binding-row ${pendingBinding===action?'listening':''}" data-action="bind-key" data-id="${action}"><span>${label}</span><kbd>${keyName(preferences.keys[action])}</kbd></button>`).join('')}</div><h3>コントローラー</h3><div class="pad-bindings">${Object.entries(preferences.pad).map(([action,index])=>`<label><span>${ACTION_LABELS[action]}</span><select data-pad-binding="${action}">${PAD_LABELS.slice(0,12).map((label,i)=>`<option value="${i}" ${index===i?'selected':''}>${label}</option>`).join('')}</select></label>`).join('')}</div><p class="hint">標準Gamepad API対応のコントローラーを接続しいずれかのボタンを押してください　接続中もマウス・タッチ・キーボードを併用できます</p><div class="actions"><button class="btn" data-action="bindings-reset">割り当てを初期化</button><button class="btn primary" data-action="close">戻る</button></div>`,true)}
function focusables(){const root=modal?$('#modal-root'):entrance?$('.scene-entrance'):$('#app');return [...(root?.querySelectorAll?.('button:not([disabled]),select,input:not([type="hidden"]),summary,[role="button"][tabindex]')||[])].filter(el=>{const r=el.getBoundingClientRect?.();return r&&r.width>0&&r.height>0})}
function focusHand(delta){const cards=[...(document.querySelectorAll?.('.hand .card:not([disabled])')||[])];if(!cards.length)return;let index=cards.indexOf(document.activeElement);index=(index+delta+cards.length)%cards.length;if(compactLayout()){phoneScreens.reveal(cards[index]);cards[index].focus({preventScroll:true})}else{cards[index].focus();cards[index].scrollIntoView({block:'nearest',inline:'nearest'})}}
function gamepadMove(direction){const active=document.activeElement;if(active&&['SELECT','INPUT'].includes(active.tagName)&&['left','right'].includes(direction)){const delta=direction==='left'?-1:1;if(active.tagName==='SELECT'){active.selectedIndex=Math.max(0,Math.min(active.options.length-1,active.selectedIndex+delta));active.dispatchEvent(new Event('change',{bubbles:true}))}else if(active.type==='range'){active.value=String(Math.max(Number(active.min||0),Math.min(Number(active.max||100),Number(active.value)+delta*5)));active.dispatchEvent(new Event('input',{bubbles:true}))}return}const next=directionalTarget(focusables(),active,direction);next?.focus();next?.scrollIntoView({block:'nearest',inline:'nearest'});document.documentElement.setAttribute('data-gamepad','on')}
function gamepadCommand(action){document.documentElement?.setAttribute('data-gamepad','on');mixer.unlock();if(action==='confirm'){const active=document.activeElement,items=focusables();if(!items.includes(active)){items[0]?.focus();return}const wasCard=active.dataset?.action==='card';active.click?.();if(wasCard&&!busy){const target=$('.card-target-dock button')||$('.selection-tray [data-action="cast"]');target?.focus()}return}if(action==='cancel'){if(entrance){clearEntrance();return}if(modal){if(modal==='カードを拡大'&&zoomReturn){closeLargeCard();return}if(modalBack())return;closeModal();return}if(state.phase==='battle'&&!busy){state.battle.selected=null;render()}return}if(action==='menu'){openMenu();return}if(action==='map'&&!inTitle){openMap();return}if(action==='previous'||action==='next'){focusHand(action==='previous'?-1:1);return}if(action==='details'){const c=state.battle?.hand?.[state.battle.selected];if(c)openCard(c.id,c.uid);return}if(action==='endTurn'&&!inTitle&&!modal&&!entrance)runTurn()}
const controller=new GamepadNavigator({bindings:()=>preferences.pad,command:gamepadCommand,move:gamepadMove,onConnect:()=>toast('コントローラーを接続しました　設定から操作を変更できます')});controller.start();window.addEventListener('gamepadconnected',()=>controller.start());

function shopUpgradeScreen(){const f=state.shopForge;return `<section class="panel content-panel shop-forge-screen"><div class="result-crest">${icon('anvil',50)}</div><div class="eyebrow">CARD UPGRADE</div><h2>三つの灯から一つを鍛える</h2><p class="intro">抽選された${f.cards.length}枚のうち、必ず1枚を強化します<br>どのカードを選んでも <b>${f.price} G</b>。強化回数による追加料金はありません</p><div class="reward-cards">${f.cards.map(uid=>{const card=state.deck.find(c=>c.uid===uid),offer=E.upgradeOffer(state,uid);return `<article>${cardHTML(card,0,'upgradeCard')}<div class="shop-upgrade-caption"><p>${esc(upgradeLabel(card,offer))}</p><button class="btn primary" data-action="upgradeCard" data-uid="${uid}">前後を比較 · ${f.price} G</button></div></article>`}).join('')}</div><p class="warning center">この強化はキャンセルできません　必ず1枚を選んでください</p><p class="hint center">次の強化：${E.shopPrice(state,110+((state.shopUpgrades||0)+1)*70)} G</p></section>`}

function upgradeLabel(card,offer){return localizedUpgradeName(E.CARDS[card.id],offer.variant,preferences.language||'ja',translateText).replace(/^(共通・|Shared:\s*|通用·)/u,'')}
registerTranslations([['への変化',' — upgrade preview','的强化变化'],['共通強化','Shared upgrade','通用强化'],['カード固有強化','Card-specific upgrade','卡牌专属强化'],['継承された強化','Legacy upgrade','继承的强化'],['必須3択','Mandatory choice of 3','三选一，必须强化'],['三つの灯から一つを鍛える','Choose one of three cards to forge.','从三盏灯中锻造一盏']]);

function openCopyPreview(uid){const card=state.deck.find(c=>c.uid===uid);if(!card||E.CARDS[card.id].special)return;rememberDeckPosition(uid);modal='カードのコピーを確認';modalBase(`<div class="eyebrow">MEMORY’S IMPRESSION</div><h2>この灯をもう一つ</h2><div class="copy-preview">${cardHTML(card,0,'large-preview').replace('<button','<div').replace('</button>','</div>')}</div><p>このカードの強化${card.up}回と合成済みの効果をそのまま引き継ぎます　元のカードも残ります</p><p class="warning">確定すると祝福の宿場の恩恵を1回消費します</p><div class="actions"><button class="btn" data-action="copy-back">別のカードを選ぶ</button><button class="btn primary" data-action="copy-confirm" data-uid="${uid}">このカードをコピー</button></div>`,true)}
registerTranslations([['カードをコピー','Copy a card','复制卡牌'],['カードのコピーを確認','Confirm card copy','确认复制卡牌'],['記憶の写し','Memory’s impression','记忆之印'],['所持カード1枚をコピー','Copy 1 owned card','复制1张已有卡牌'],['このカードをコピー','Copy this card','复制此卡牌'],['別のカードを選ぶ','Choose another card','选择其他卡牌'],['この灯をもう一つ','One more light.','再添一盏灯'],['強化や合成の効果ごと増やせる1枚（特殊カードは不可）','Create a new copy preserving upgrades and fusion effects. Special cards cannot be copied. Review before confirming.','复制一张新卡，保留强化和融合效果　特殊卡不能复制　确认后才会执行']]);

function goddessScreen(){return `<section class="panel content-panel goddess-screen"><img class="goddess-art" src="assets/lake-goddess.webp" alt=""><div class="goddess-reflection" aria-hidden="true"></div><div class="result-crest">${icon('moon',56)}</div><div class="eyebrow">THE LADY OF THE LAKE</div><h2>湖の女神</h2><p class="intro">「望む変化をお選びなさい。」<br>ランダムな3つの恩恵から1つを選び、その後に付与するカードを選べます</p><div class="option-list">${state.goddess.offers.map(id=>{const g=E.GODDESS_GIFTS.find(g=>g.id===id),eligible=state.deck.some(c=>E.goddessEligible(state,c,id));return `<button class="option" ${!eligible?'disabled':''} data-action="goddess-gift" data-id="${id}">${icon(id==='refund'?'book':id==='cost'?'leaf':'moon',28)}<span><strong>${g.name}</strong><small>${g.desc}${!eligible?' 現在、条件を満たすカードがありません':''}</small><em>${id==='refund'?'強化ポイントが1以上のカードのみ　性能はそのまま、ポイント−1':'選んだ効果は必ず付与　追加の効果・代償はランダム　強化ポイント+1'}</em></span>${icon('arrow',18)}</button>`}).join('')}</div><div class="reward-actions"><button class="btn" data-action="leave">恩恵を受けずに進む</button></div></section>`}
function announceCardUpgrade(uid){pendingDeckRevealUid=uid;const card=state.deck.find(c=>c.uid===uid);if(!card)return;const c=E.cardValues(card,state),previous=state.lastCardUpgrade;toast(`${displayCardName(c)}${card.up?'＋'+card.up:''}を更新。${previous&&previous.beforeCost!==c.cost?'気力 '+previous.beforeCost+'→'+c.cost:'気力 '+c.cost}。所持デッキで確認できます`)}
function openGoddessPreview(uid){const offer=E.goddessUpgradeOffer(state,uid);if(!offer)return;rememberDeckPosition(uid);save();const g=E.GODDESS_GIFTS.find(g=>g.id===offer.gift);modal='女神の恩恵を確認';modalBase(`<div class="eyebrow">GUARANTEED BLESSING</div><h2>${g.name}</h2><p class="goddess-guarantee">${g.desc}</p><div class="upgrade-comparison comparison-pair">${[offer.before,offer.after].map((card,i)=>`<section><h3>${i?'付与後':'現在'} / 強化ポイント ${card.up}/3</h3>${cardHTML(card,0,'preview-card').replace('<button','<div').replace('</button>','</div>')}<ul>${cardLines(card,state).map(line=>`<li>${line}</li>`).join('')}</ul><strong>消費気力 ${E.cardValues(card,state).cost}</strong></section>`).join('')}</div><p class="warning">${offer.gift==='refund'?'効果を保ったまま強化ポイントを1戻します　この恩恵でポイントは増えません':'選んだ恩恵は必ず付きます<br>ほかの効果や代償はこの候補で決まり再読み込みしても変わりません<br>強化ポイントを1使います'}</p><div class="actions"><button class="btn" data-action="goddess-back">別のカードを確認</button><button class="btn" data-action="goddess-menu">恩恵を選び直す</button><button class="btn primary" data-action="goddess-confirm" data-uid="${uid}">この恩恵を確定</button></div>`,true)}

