let pendingBalance=null;export function receiveBalanceUpdate(config){pendingBalance=config;tryApplyBalance()}
function tryApplyBalance(){if(!pendingBalance||busy||state.phase==='battle'||state.cutscene||state.travel||modal)return;const next=pendingBalance;pendingBalance=null;try{applyBalance(next);reconcileBalance(state);save();render();toast('公開された性能設定を反映しました')}catch{}}
setInterval(tryApplyBalance,3000);

function encyclopediaFilter(event){if(modal!=='図鑑'||!['encyclopedia-search','encyclopedia-known','encyclopedia-sort','encyclopedia-byowner'].includes(event.target?.id))return;const search=$('#encyclopedia-search'),known=$('#encyclopedia-known');encyclopediaState={...encyclopediaState,query:search?.value||'',knownOnly:!!known?.checked,sort:$('#encyclopedia-sort')?.value||encyclopediaState.sort,byOwner:$('#encyclopedia-byowner')?!!$('#encyclopedia-byowner').checked:encyclopediaState.byOwner,page:0};const current=$('#modal-root .encyclopedia-view');if(!current)return;const replacement=document.createElement('div');replacement.innerHTML=encyclopediaView(progress,{...encyclopediaState,...encyclopediaOptions(),size:encyclopediaSize()});for(const selector of ['.encyclopedia-grid','.encyclopedia-pages','.encyclopedia-count']){const old=current.querySelector(selector),next=replacement.querySelector(selector);if(old&&next)old.replaceWith(next)}}

// ── 画面（モーダル）の履歴：「戻る」で1つ前の画面へ戻る ──
const modalHistory={stack:[],current:null,currentModal:'',back:false};
function relabelBackButtons(){if(!modalHistory.stack.length&&!(modalHistory.currentModal&&modalHistory.currentModal!==modal))return;const label=translateText('戻る',preferences.language||'ja');for(const button of document.querySelectorAll('#modal-root .actions [data-action="close"]'))if(/ゲームに戻る|旅へ戻る|元の画面に戻る|Return to game|Back to game/.test(button.textContent))button.textContent=label}
function trackModal(open){const wrapped=function(...args){const prevModal=modal,prevOpen=modalHistory.current,prevFor=modalHistory.currentModal,result=open.apply(this,args);if(!modal)return result;if(!modalHistory.back){if(!prevModal)modalHistory.stack=[];else if(prevModal!==modal){const i=modalHistory.stack.findIndex(e=>e.modal===modal);if(i>=0)modalHistory.stack.length=i;else if(prevOpen&&prevFor===prevModal)modalHistory.stack.push({modal:prevModal,open:prevOpen})}}modalHistory.current=()=>wrapped(...args);modalHistory.currentModal=modal;relabelBackButtons();return result};return wrapped}
function modalBack(){
 // 履歴に載らない確認画面などからはその下の画面へ戻る
 const target=modalHistory.currentModal&&modalHistory.currentModal!==modal?{open:modalHistory.current}:modalHistory.stack.pop();
 if(!target?.open)return false;
 modalHistory.back=true;try{target.open()}finally{modalHistory.back=false}
 relabelBackButtons();sound('cancel');return true;
}
openMenu=trackModal(openMenu);openSettings=trackModal(openSettings);openAudio=trackModal(openAudio);openControls=trackModal(openControls);openSlots=trackModal(openSlots);openHelp=trackModal(openHelp);openAchievements=trackModal(openAchievements);openShare=trackModal(openShare);openJournal=trackModal(openJournal);openRoles=trackModal(openRoles);openRelics=trackModal(openRelics);openMap=trackModal(openMap);openEncyclopedia=trackModal(openEncyclopedia);openBackup=trackModal(openBackup);openPassword=trackModal(openPassword);
